\t\tSize = UDim2.new(0.55, 0, 0, 16),\n\t\t\tPosition = UDim2.fromOffset(0, 8),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Torso Camera Control",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 11,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = camCard,\n\t\t})\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(0.55, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 24),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Lean & turn body with camera look direction",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = camCard,\n\t\t})\n\n\t\tlocal tcState = _G._LumenLimbsTorsoCamControl or false\n\t\tlocal toggleBtn = new("TextButton", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tSize = UDim2.fromOffset(36, 18),\n\t\t\tPosition = UDim2.new(1, 0, 0, 8),\n\t\t\tBackgroundColor3 = tcState and Color3.fromRGB(255, 255, 255) or T.surface3,\n\t\t\tText = tcState and "ON" or "OFF",\n\t\t\tTextColor3 = tcState and Color3.fromRGB(15, 15, 20) or T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = camCard,\n\t\t}, { corner(6) })\n\t\tstroke(T.line, 1, 0.5).Parent = toggleBtn\n\t\tskinToggle(toggleBtn)\n\n\t\ttoggleBtn.MouseButton1Click:Connect(function()\n\t\t\ttcState = not tcState\n\t\t\ttoggleBtn.BackgroundColor3 = tcState and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\ttoggleBtn.Text = tcState and "ON" or "OFF"\n\t\t\ttoggleBtn.TextColor3 = tcState and Color3.fromRGB(15, 15, 20) or T.text3\n\t\t\t_G._LumenLimbsTorsoCamControl = tcState\n\t\t\tpcall(updateStandaloneTrackers)\n\t\tend)\n\n\t\tlocal modeBtn = new("TextButton", {\n\t\t\tSize = UDim2.fromOffset(88, 20),\n\t\t\tPosition = UDim2.fromOffset(0, 40),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tText = "Mode: " .. (_G._LumenLimbsTorsoCamMode or "360"),\n\t\t\tTextColor3 = T.text2,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = camCard,\n\t\t}, { corner(5) })\n\t\tstroke(T.line, 1, 0.5).Parent = modeBtn\n\n\t\tlocal modes = {"360", "Locked", "Free"}\n\t\tlocal modeIdx = 1\n\t\tmodeBtn.MouseButton1Click:Connect(function()\n\t\t\tmodeIdx = (modeIdx % #modes) + 1\n\t\t\t_G._LumenLimbsTorsoCamMode = modes[modeIdx]\n\t\t\tmodeBtn.Text = "Mode: " .. modes[modeIdx]\n\t\tend)\n\tend\n\n\t-- Pole Mode Card (Place arms/legs down into ground and stretch upwards infinitely)\n\tdo\n\t\tlocal poleCard = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 154),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = trackersPanelFrame,\n\t\t}, { corner(8), pad(8, 10, 8, 10) })\n\t\tstroke(T.line, 1, 0.4).Parent = poleCard\n\n\t\t-- Header Row: Title & Subtitle\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(0.65, 0, 0, 16),\n\t\t\tPosition = UDim2.fromOffset(0, 0),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Pole Mode",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 11,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(0.65, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 16),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Plant limbs down & extend height",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\t-- Master Pole Toggle Button (Top Right)\n\t\tlocal isPoleOn = _G._LumenPoleModeEnabled or false\n\t\tlocal poleToggleBtn = new("TextButton", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.new(1, 0, 0, 0),\n\t\t\tSize = UDim2.fromOffset(36, 18),\n\t\t\tBackgroundColor3 = isPoleOn and Color3.fromRGB(255, 255, 255) or T.surface3,\n\t\t\tText = isPoleOn and "ON" or "OFF",\n\t\t\tTextColor3 = isPoleOn and Color3.fromRGB(15, 15, 20) or T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = poleCard,\n\t\t}, { corner(6) })\n\t\tstroke(T.line, 1, 0.5).Parent = poleToggleBtn\n\t\tskinToggle(poleToggleBtn)\n\n\t\tpoleToggleBtn.MouseButton1Click:Connect(function()\n\t\t\tisPoleOn = not isPoleOn\n\t\t\t_G._LumenPoleModeEnabled = isPoleOn\n\t\t\tpoleToggleBtn.BackgroundColor3 = isPoleOn and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\tpoleToggleBtn.Text = isPoleOn and "ON" or "OFF"\n\t\t\tpoleToggleBtn.TextColor3 = isPoleOn and Color3.fromRGB(15, 15, 20) or T.text3\n\t\t\tpcall(updateStandaloneTrackers)\n\t\tend)\n\n\t\t-- Limb Selection Row (Right Arm, Left Arm, Both Arms, Right Leg, Left Leg, Legs, All Limbs)\n\t\t_G._LumenPoleLimbs = _G._LumenPoleLimbs or "Both Arms"\n\t\tlocal limbOptions = { "Right", "Left", "Both", "R.Leg", "L.Leg", "Legs", "All" }\n\t\tlocal limbMap = {\n\t\t\t["Right"] = "Right Arm",\n\t\t\t["Left"]  = "Left Arm",\n\t\t\t["Both"]  = "Both Arms",\n\t\t\t["R.Leg"] = "Right Leg",\n\t\t\t["L.Leg"] = "Left Leg",\n\t\t\t["Legs"]  = "Legs",\n\t\t\t["All"]   = "All Limbs",\n\t\t}\n\n\t\tlocal limbRow = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 22),\n\t\t\tPosition = UDim2.fromOffset(0, 36),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tParent = limbRow or poleCard,\n\t\t})\n\t\tlimbRow.Parent = poleCard\n\t\tnew("UIListLayout", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tPadding = UDim.new(0, 4),\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t\tParent = limbRow,\n\t\t})\n\n\t\tlocal limbBtns = {}\n\t\tlocal function updateLimbBtns()\n\t\t\tfor tag, b in pairs(limbBtns) do\n\t\t\t\tlocal full = limbMap[tag]\n\t\t\t\tlocal active = (_G._LumenPoleLimbs == full)\n\t\t\t\tb.BackgroundColor3 = active and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\t\tb.TextColor3 = active and Color3.fromRGB(15, 15, 20) or T.text2\n\t\t\tend\n\t\tend\n\n\t\tfor idx, tag in ipairs(limbOptions) do\n\t\t\tlocal full = limbMap[tag]\n\t\t\tlocal b = new("TextButton", {\n\t\t\t\tSize = UDim2.new(1/#limbOptions, -4, 1, 0),\n\t\t\t\tBackgroundColor3 = (_G._LumenPoleLimbs == full) and Color3.fromRGB(255, 255, 255) or T.surface3,\n\t\t\t\tText = tag,\n\t\t\t\tTextColor3 = (_G._LumenPoleLimbs == full) and Color3.fromRGB(15, 15, 20) or T.text2,\n\t\t\t\tTextSize = 8,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tAutoButtonColor = false,\n\t\t\t\tLayoutOrder = idx,\n\t\t\t\tParent = limbRow,\n\t\t\t}, { corner(5) })\n\t\t\tstroke(T.line, 1, 0.4).Parent = b\n\t\t\tlimbBtns[tag] = b\n\t\t\tb.MouseButton1Click:Connect(function()\n\t\t\t\t_G._LumenPoleLimbs = full\n\t\t\t\tupdateLimbBtns()\n\t\t\tend)\n\t\tend\n\n\t\t-- Pole Length Slider (Default 14 studs, draggable and extends infinitely)\n\t\t_G._LumenPoleLength = _G._LumenPoleLength or 14\n\t\tlocal lenValLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 66),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = string.format("Length: %d studs", math.floor(_G._LumenPoleLength)),\n\t\t\tTextColor3 = T.text2,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\t-- Quick Step Increment Buttons (+10, +50, -10)\n\t\tlocal stepControls = new("Frame", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.new(1, 0, 0, 64),\n\t\t\tSize = UDim2.fromOffset(110, 18),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tParent = poleCard,\n\t\t})\n\t\tnew("UIListLayout", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tPadding = UDim.new(0, 4),\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Right,\n\t\t\tParent = stepControls,\n\t\t})\n\n\t\tlocal function createStepBtn(txt, delta)\n\t\t\tlocal sb = new("TextButton", {\n\t\t\t\tSize = UDim2.fromOffset(32, 18),\n\t\t\t\tBackgroundColor3 = T.surface3,\n\t\t\t\tText = txt,\n\t\t\t\tTextColor3 = T.text1,\n\t\t\t\tTextSize = 8,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tAutoButtonColor = false,\n\t\t\t\tParent = stepControls,\n\t\t\t}, { corner(4) })\n\t\t\tstroke(T.line, 1, 0.4).Parent = sb\n\t\t\tsb.MouseButton1Click:Connect(function()\n\t\t\t\t_G._LumenPoleLength = math.max(1, (_G._LumenPoleLength or 14) + delta)\n\t\t\t\tlenValLabel.Text = string.format("Length: %d studs", math.floor(_G._LumenPoleLength))\n\t\t\tend)\n\t\tend\n\t\tcreateStepBtn("-10", -10)\n\t\tcreateStepBtn("+10", 10)\n\t\tcreateStepBtn("+50", 50)\n\n\t\t-- Slider Track\n\t\tlocal poleTrack = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 12),\n\t\t\tPosition = UDim2.fromOffset(0, 88),\n\t\t\tBackgroundColor3 = Color3.fromRGB(22, 22, 28),\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = poleCard,\n\t\t}, { corner(6) })\n\t\tstroke(T.line, 1, 0.35).Parent = poleTrack\n\n\t\tlocal poleInitialPct = math.clamp((_G._LumenPoleLength - 1) / 99, 0, 1)\n\t\tlocal poleProgress = new("Frame", {\n\t\t\tSize = UDim2.new(poleInitialPct, 0, 1, 0),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = poleTrack,\n\t\t}, { corner(6) })\n\t\tnew("UIGradient", {\n\t\t\tColor = ColorSequence.new{\n\t\t\t\tColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),\n\t\t\t\tColorSequenceKeypoint.new(1, Color3.fromRGB(195, 195, 210)),\n\t\t\t},\n\t\t\tTransparency = NumberSequence.new{\n\t\t\t\tNumberSequenceKeypoint.new(0, 0.85),\n\t\t\t\tNumberSequenceKeypoint.new(1, 0),\n\t\t\t},\n\t\t\tOffset = Vector2.new(0, 0.5),\n\t\t\tRotation = 2,\n\t\t\tParent = poleProgress,\n\t\t})\n\n\t\tlocal poleHandle = new("Frame", {\n\t\t\tSize = UDim2.fromOffset(35, 18),\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tPosition = UDim2.new(poleInitialPct, (1 - 2 * poleInitialPct) * (35 / 2 - 2), 0.5, 0),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tBorderSizePixel = 0,\n\t\t\tZIndex = 5,\n\t\t\tParent = poleTrack,\n\t\t}, { corner(9) })\n\t\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.7).Parent = poleHandle\n\t\taddHandleGlow(poleHandle)\n\n\t\tlocal poleDragging = false\n\t\tlocal function updatePoleFromInput(input)\n\t\t\tlocal absX = poleTrack.AbsolutePosition.X\n\t\t\tlocal absW = poleTrack.AbsoluteSize.X\n\t\t\tif absW <= 0 then return end\n\t\t\tlocal p = math.clamp((input.Position.X - absX) / absW, 0, 1)\n\t\t\t-- Non-linear scaling up to 100 studs via slider, can go higher indefinitely via + buttons\n\t\t\tlocal computedLen = math.floor(1 + (p * 99))\n\t\t\t_G._LumenPoleLength = computedLen\n\t\t\tglide(poleProgress, { Size = UDim2.new(p, 0, 1, 0) })\n\t\t\tglide(poleHandle, { Position = UDim2.new(p, (1 - 2 * p) * (35 / 2 - 2), 0.5, 0) })\n\t\t\tlenValLabel.Text = string.format("Length: %d studs", computedLen)\n\t\tend\n\n\t\tpoleTrack.InputBegan:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tpoleDragging = true\n\t\t\t\tupdatePoleFromInput(input)\n\t\t\tend\n\t\tend)\n\t\tuserInputService.InputChanged:Connect(function(input)\n\t\t\tif poleDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then\n\t\t\t\tupdatePoleFromInput(input)\n\t\t\tend\n\t\tend)\n\n\t\tuserInputService.InputEnded:Connect(function(input)\n\t\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\t\tpoleDragging = false\n\t\t\tend\n\t\tend)\n\n\t\t-- Manual Direct Input Box for Infinite Length\n\t\tlocal directInputLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(0.45, 0, 0, 20),\n\t\t\tPosition = UDim2.fromOffset(0, 112),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Custom Length (studs):",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = poleCard,\n\t\t})\n\n\t\tlocal directInputBox = new("TextBox", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.new(1, 0, 0, 110),\n\t\t\tSize = UDim2.fromOffset(72, 22),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tTextColor3 = T.text1,\n\t\t\tText = tostring(math.floor(_G._LumenPoleLength or 14)),\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tClearTextOnFocus = false,\n\t\t\tParent = poleCard,\n\t\t}, { corner(5), pad(0, 6, 0, 6) })\n\t\tstroke(T.line, 1, 0.4).Parent = directInputBox\n\n\t\tdirectInputBox.FocusLost:Connect(function()\n\t\t\tlocal num = tonumber(directInputBox.Text)\n\t\t\tif num and num > 0 then\n\t\t\t\t_G._LumenPoleLength = num\n\t\t\t\tlenValLabel.Text = string.format("Length: %d studs", math.floor(num))\n\t\t\t\tlocal clampedP = math.clamp((num - 1) / 99, 0, 1)\n\t\t\t\tglide(poleProgress, { Size = UDim2.new(clampedP, 0, 1, 0) })\n\t\t\t\tglide(poleHandle, { Position = UDim2.new(clampedP, (1 - 2 * clampedP) * (35 / 2 - 2), 0.5, 0) })\n\t\t\telse\n\t\t\t\tdirectInputBox.Text = tostring(math.floor(_G._LumenPoleLength or 14))\n\t\t\tend\n\t\tend)\n\tend\n\n\t-- Fly Parts: fly the head (plus optional torso / arms / legs in a sit pose)\n\tcreateTrackerCard("Fly Parts", "WASD move, Space up, Ctrl down, Shift fast", false, function(st)\n\t\tif st then\n\t\t\tlocal ok, err = _G.LumenFlyStart()\n\t\t\tif not ok then\n\t\t\t\tif _G.updateTrackerUI_Fly then _G.updateTrackerUI_Fly(false) end\n\t\t\t\twarn("[Lumen] Fly: " .. tostring(err))\n\t\t\tend\n\t\telse\n\t\t\t_G.LumenFlyStop()\n\t\tend\n\tend, true, function() return _G._LumenFlyKey end, function(k) _G._LumenFlyKey = k end, "updateTrackerUI_Fly")\n\tdo\n\t\tlocal flyCard = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 78),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTrans