tlocal function paint()\n\t\t\t\tlocal on = _G._LumenFlyParts[d[1]]\n\t\t\t\tb.BackgroundColor3 = on and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\t\tb.TextColor3 = on and Color3.fromRGB(15, 15, 20) or T.text2\n\t\t\tend\n\t\t\tpaint()\n\t\t\tb.MouseButton1Click:Connect(function()\n\t\t\t\t_G._LumenFlyParts[d[1]] = not _G._LumenFlyParts[d[1]]\n\t\t\t\tpaint()\n\t\t\tend)\n\t\tend\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 12), Position = UDim2.fromOffset(0, 52),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Torso + legs make your body sit behind the head",\n\t\t\tTextColor3 = T.text3, TextSize = 8, Font = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left, Parent = flyCard,\n\t\t})\n\tend\n\n\t-- Player Attach Card: attach any limb (arms/legs) to different players/targets\n\tdo\n\t\tlocal Players = game:GetService("Players")\n\t\tlocal attachCard = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 316),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = trackersPanelFrame,\n\t\t}, { corner(8), pad(8, 10, 8, 10) })\n\t\tstroke(T.line, 1, 0.4).Parent = attachCard\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 16),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Attach to Player",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 11,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = attachCard,\n\t\t})\n\t\tlocal statusLbl = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 18),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\tParent = attachCard,\n\t\t})\n\t\tlocal clearBtn = new("TextButton", {\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tSize = UDi