n\t\t\treturn b\n\t\tend\n\n\t\tlocal LIMBS = {\n\t\t\t{ key = "RightArm", label = "R Arm", short = "R.Arm" },\n\t\t\t{ key = "LeftArm",  label = "L Arm", short = "L.Arm" },\n\t\t\t{ key = "RightLeg", label = "R Leg", short = "R.Leg" },\n\t\t\t{ key = "LeftLeg",  label = "L Leg", short = "L.Leg" },\n\t\t}\n\t\tlocal limbBtns = {}\n\t\tlocal partBtns = {}\n\t\tlocal refreshPlrList\n\n\t\tlocal function targetName(t)\n\t\t\tif t.player then return t.player.DisplayName or t.player.Name end\n\t\t\tif t.model then return t.model.Name end\n\t\t\treturn "Point"\n\t\tend\n\t\tlocal function paint(btn, on)\n\t\t\tbtn.BackgroundColor3 = on and Color3.fromRGB(255, 255, 255) or T.surface3\n\t\t\tbtn.TextColor3 = on and Color3.fromRGB(15, 15, 20) or T.text2\n\t\tend\n\t\tlocal function refreshAll()\n\t\t\tfor i, l in ipairs(LIMBS) do\n\t\t\t\tlocal b = limbBtns[i]\n\t\t\t\tif b then\n\t\t\t\t\tpaint(b, _G._LumenAttachSelLimb == l.key)\n\t\t\t\t\tb.Text = l.label .. (_G._LumenLimbAttach[l.key] and " \u{2022}" or "")\n\t\t\t\tend\n\t\t\tend\n\t\t\tpaint(partBtns.Torso, _G._LumenArmAttachPart == "Torso")\n\t\t\tpaint(partBtns.Head, _G._LumenArmAttachPart == "Head")\n\t\t\tlocal parts = {}\n\t\t\tfor _, l in ipairs(LIMBS) do\n\t\t\t\tlocal t = _G._LumenLimbAttach[l.key]\n\t\t\t\tif t then table.insert(parts, l.short .. "\u{2192}" .. targetName(t)) end\n\t\t\tend\n\t\t\tif #parts > 0 then\n\t\t\t\tstatusLbl.Text = table.concat(parts, "  ")\n\t\t\t\tstatusLbl.TextColor3 = T.accent\n\t\t\telse\n\t\t\t\tstatusLbl.Text = "Pick a limb, then a player (or use Click Pick)"\n\t\t\t\tstatusLbl.TextColor3 = T.text3\n\t\t\tend\n\t\t\tlocal pick = _G._LumenAttachPickMode == true\n\t\t\tpickBtn.Text = pick and "Click Pick: ON" or "Click Pick: OFF"\n\t\t\tpaint(pickBtn, pick)\n\t\t\tif refreshPlrList then refreshPlrList() end\n\t\tend\n\t\t_G._LumenUpdateAttachUI = refreshAll\n\n\t\tlocal limbRow = makeRow(62)\n\t\tfor i, l in ipairs(LIMBS) do\n\t\t\tlimbBtns[i] = segBtn(limbRow, l.label, i, function()\n\t\t\t\t_G._LumenAttachSelLimb = l.key\n\t\t\t\trefreshAll()\n\t\t\tend)\n\t\tend\n\t\tlocal partRow = makeRow(90)\n\t\tpartBtns.Torso = segBtn(partRow, "Torso", 1, function()\n\t\t\t_G._LumenArmAttachPart = "Torso"\n\t\t\tfor _, t in pairs(_G._LumenLimbAttach) do if t.player or t.model then t.part = "Torso" end end\n\t\t\trefreshAll()\n\t\tend)\n\t\tpartBtns.Head = segBtn(partRow, "Head", 2, function()\n\t\t\t_G._LumenArmAttachPart = "Head"\n\t\t\tfor _, t in pairs(_G._LumenLimbAttach) do if t.player or t.model then t.part = "Head" end end\n\t\t\trefreshAll()\n\t\tend)\n\n\t\tlocal filterText = ""\n\t\tlocal playerSearch = new("TextBox", {\n\t\t\tSize = UDim2.new(1, 0, 0, 24),\n\t\t\tPosition = UDim2.fromOffset(0, 118),\n\t\t\tBackgroundColor3 = T.surface,\n\t\t\tTextColor3 = T.text1,\n\t\t\tPlaceholderText = "Search players...",\n\t\t\tPlaceholderColor3 = T.text3,\n\t\t\tTextSize = 10,\n\t\t\tText = "",\n\t\t\tClearTextOnFocus = false,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = attachCard,\n\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\t\tstroke(T.line, 1, 0.4).Parent = playerSearch\n\n\t\tlocal playerListScroll = new("ScrollingFrame", {\n\t\t\tSize = UDim2.new(1, 0, 1, -150),\n\t\t\tPosition = UDim2.fromOffset(0, 148),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tBorderSizePixel = 0,\n\t\t\tScrollBarThickness = 0,\n\t\t\tAutomaticCanvasSize = Enum.AutomaticSize.Y,\n\t\t\tCanvasSize = UDim2.new(),\n\t\t\tParent = attachCard,\n\t\t}, { pad(2, 4, 4, 4) })\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = playerListScroll })\n\n\t\tclearBtn.MouseButton1Click:Connect(function()\n\t\t\ttable.clear(_G._LumenLimbAttach)\n\t\t\tpcall(updateStandaloneTrackers)\n\t\t\trefreshAll()\n\t\tend)\n\t\tpickBtn.MouseButton1Click:Connect(function()\n\t\t\t_G._LumenAttachPickMode = not (_G._LumenAttachPickMode == true)\n\t\t\trefreshAll()\n\t\tend)\n\n\t\trefreshPlrList = function()\n\t\t\tfor _, ch in ipairs(playerListScroll:GetChildren()) do\n\t\t\t\tif ch:IsA("GuiObject") then ch:Destroy() end\n\t\t\tend\n\t\t\tlocal lp = Players.LocalPlayer\n\t\t\tlocal sel = _G._LumenAttachSelLimb\n\t\t\tfor _, p in ipairs(Players:GetPlayers()) do\n\t\t\t\tif p ~= lp then\n\t\t\t\t\tlocal dName = p.DisplayName or p.Name\n\t\t\t\t\tlocal uName = "@" .. p.Name\n\t\t\t\t\tlocal match = (filterText == "")\n\t\t\t\t\t\tor string.find(string.lower(dName), filterText, 1, true)\n\t\t\t\t\t\tor string.find(string.lower(uName), filterText, 1, true)\n\t\t\t\t\tif match then\n\t\t\t\t\t\tlocal cur = _G._LumenLimbAttach[sel]\n\t\t\t\t\t\tlocal isCur = cur and cur.player == p\n\t\t\t\t\t\tlocal on = {}\n\t\t\t\t\t\tfor _, l in ipairs(LIMBS) do\n\t\t\t\t\t\t\tlocal t = _G._LumenLimbAttach[l.key]\n\t\t\t\t\t\t\tif t and t.player == p then table.insert(on, l.short) end\n\t\t\t\t\t\tend\n\t\t\t\t\t\tlocal plate = new("Frame", {\n\t\t\t\t\t\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\t\t\t\t\t\tBackgroundColor3 = #on > 0 and Color3.fromRGB(28, 38, 30) or T.surface3,\n\t\t\t\t\t\t\tBackgroundTransparency = 0.35,\n\t\t\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\t\t\tParent = playerListScroll,\n\t\t\t\t\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\t\t\t\t\t\tstroke(#on > 0 and T.accent or T.line, 1, #on > 0 and 0.8 or 0.4).Parent = plate\n\t\t\t\t\t\tlocal thumb = new("ImageLabel", {\n\t\t\t\t\t\t\tAnchorPoint = Vector2.new(0, 0.5),\n\t\t\t\t\t\t\tPosition = UDim2.new(0, 0, 0.5, 0),\n\t\t\t\t\t\t\tSize = UDim2.fromOffset(26, 26),\n\t\t\t\t\t\t\tBackgroundColor3 = T.surface2,\n\t\t\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\t\t\tImage = "rbxthumb://type=AvatarHeadShot&id=" .. p.UserId .. "&w=48&h=48",\n\t\t\t\t\t\t\tParent = plate,\n\t\t\t\t\t\t}, { corner(13) })\n\t\t\t\t\t\tstroke(T.line, 1, 0.3).Parent = thumb\n\t\t\t\t\t\tlocal info = new("Frame", {\n\t\t\t\t\t\t\tAnchorPoint = Vector2.new(0, 0.5),\n\t\t\t\t\t\t\tPosition = UDim2.new(0, 34, 0.5, 0),\n\t\t\t\t\t\t\tSize = UDim2.new(1, -100, 1, 0),\n\t\t\t\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\t\t\t\tParent = plate,\n\t\t\t\t\t\t})\n\t\t\t\t\t\tnew("UIListLayout", { VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 1), Parent = info })\n\t\t\t\t\t\tnew("TextLabel", {\n\t\t\t\t\t\t\tSize = UDim2.new(1, 0, 0, 14), BackgroundTransparency = 1, Text = dName,\n\t\t\t\t\t\t\tTextColor3 = T.text1, TextSize = 10, Font = Enum.Font.BuilderSansBold,\n\t\t\t\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = info,\n\t\t\t\t\t\t})\n\t\t\t\t\t\tnew("TextLabel", {\n\t\t\t\t\t\t\tSize = UDim2.new(1, 0, 0, 12), BackgroundTransparency = 1,\n\t\t\t\t\t\t\tText = #on > 0 and table.concat(on, ", ") or uName,\n\t\t\t\t\t\t\tTextColor3 = #on > 0 and T.accent or T.text3, TextSize = 8.5, Font = Enum.Font.BuilderSans,\n\t\t\t\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = info,\n\t\t\t\t\t\t})\n\t\t\t\t\t\tlocal connBtn = new("TextButton", {\n\t\t\t\t\t\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\t\t\t\t\t\tPosition = UDim2.new(1, 0, 0.5, 0),\n\t\t\t\t\t\t\tSize = UDim2.fromOffset(58, 22),\n\t\t\t\t\t\t\tBackgroundColor3 = isCur and Color3.fromRGB(255, 255, 255) or T.surface,\n\t\t\t\t\t\t\tText = isCur and "Attached" or "Connect",\n\t\t\t\t\t\t\tTextColor3 = isCur and Color3.fromRGB(15, 15, 20) or T.text1,\n\t\t\t\t\t\t\tTextSize = 9,\n\t\t\t\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\t\t\tAutoButtonColor = false,\n\t\t\t\t\t\t\tParent = plate,\n\t\t\t\t\t\t}, { corner(5) })\n\t\t\t\t\t\tstroke(T.line, 1, 0.5).Parent = connBtn\n\t\t\t\t\t\tconnBtn.MouseButton1Click:Connect(function()\n\t\t\t\t\t\t\tif isCur then\n\t\t\t\t\t\t\t\t_G._LumenLimbAttach[sel] = nil\n\t\t\t\t\t\t\telse\n\t\t\t\t\t\t\t\t_G._LumenLimbAttach[sel] = { player = p, part = _G._LumenArmAttachPart or "Torso" }\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tpcall(updateStandaloneTrackers)\n\t\t\t\t\t\t\trefreshAll()\n\t\t\t\t\t\tend)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\tplayerSearch:GetPropertyChangedSignal("Text"):Connect(function()\n\t\t\tfilterText = string.lower(playerSearch.Text)\n\t\t\trefreshPlrList()\n\t\tend)\n\t\tPlayers.PlayerAdded:Connect(function() refreshPlrList() end)\n\t\tPlayers.PlayerRemoving:Connect(function(rp)\n\t\t\tif _G.LumenTeleporting then return end\n\t\t\tfor k, t in pairs(_G._LumenLimbAttach) do\n\t\t\t\tif t.player == rp then _G._LumenLimbAttach[k] = nil end\n\t\t\tend\n\t\t\trefreshAll()\n\t\tend)\n\t\trefreshAll()\n\tend\n\n\tend\n\tlocal refreshCombinePanel, getAllAnimNames\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- COMBINE / SEQUENCE BUILDER LOGIC\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t_G.combinedSequences = _G.combinedSequences or {}\n\n\tlocal draft = _G.LumenSeqDraft or { name = "", loop = false, clips = {} }\n\t_G.LumenSeqDraft = draft\n\tlocal pickerFilter = ""\n\tlocal editingIndex = nil\n\tlocal statusText, statusColor = "", nil\n\trefreshCombinePanel = nil\n\n\tlocal function fmtTime(t) return string.format("%.2fs", t) end\n\n\tfunction getAllAnimNames()\n\t\tlocal seen, out = {}, {}\n\t\tlocal function add(tbl)\n\t\t\tfor name, v in pairs(tbl or {}) do\n\t\t\t\tif type(name) == "string" and not seen[name] and not name:match("^combined:") and v ~= nil then\n\t\t\t\t\tseen[name] = true\n\t\t\t\t\ttable.insert(out, name)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tadd(animationQueue); add(transformCache); add(characterAttachments)\n\t\ttable.sort(out, function(x, y) return x:lower() < y:lower() end)\n\t\treturn out\n\tend\n\n\tlocal getAvailableAnims = getAllAnimNames\n\n\tlocal function seqTotal(clips)\n\t\tlocal t = 0\n\t\tfor _, c in ipairs(clips) do\n\t\t\tt = t + math.max(0, ((c.stop or 0) - (c.start or 0)) / math.max(0.05, math.abs(c.speed or 1)))\n\t\tend\n\t\treturn t\n\tend\n\n\tlocal function setStatus(txt, col)\n\t\tstatusText, statusColor = txt or "", col\n\tend\n\n\tlocal function makeBtn(parent, text, size, pos, bg, fg, strokeCol)\n\t\tlocal b = new("TextButton", {\n\t\t\tSize = size, Position = pos or UDim2.new(),\n\t\t\tBackgroundColor3 = bg or T.surface3,\n\t\t\tText = text, TextColor3 = fg or T.text1, TextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold, BorderSizePixel = 0, AutoButtonColor = false,\n\t\t\tZIndex = 8, Parent = parent,\n\t\t}, { corner(5) })\n\t\tstroke(strokeCol or T.line, 1, 0.5).Parent = b\n\t\treturn b\n\tend\n\n\tlocal function makeBox(parent, text, size, pos, placeholder)\n\t\tlocal tb = new("TextBox", {\n\t\t\tSize = size, Position = pos,\n\t\t\tBackgroundColor3 = T.surface,\n\t\t\tText = text, PlaceholderText = placeholder or "",\n\t\t\tPlaceholderColor3 = T.text3, TextColor3 = T.text1, TextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansMedium, ClearTextOnFocus = false,\n\t\t\tBorderSizePixel = 0, ZIndex = 8, Parent = parent,\n\t\t}, { corner(5), pad(0, 4, 0, 4) })\n\t\tstroke(T.line, 1, 0.5).Parent = tb\n\t\treturn tb\n\tend\n\n\tlocal function card(order)\n\t\tlocal c = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 0),\n\t\t\tAutomaticSize = Enum.AutomaticSize.Y,\n\t\t\tBackgroundColor3 = T.surface2, BackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0, ZIndex = 7, LayoutOrder = order, Parent = combinePanelFrame,\n\t\t}, { corner(8), pad(8, 10, 10, 10) })\n\t\tstroke(T.line, 1, 0.4).Parent = c\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c })\n\t\treturn c\n\tend\n\n\tlocal function iconBtn(parent, image, size, pos, tint, bg)\n\t\tlocal b = new("ImageButton", {\n\t\t\tSize = size, Position = pos or UDim2.new(),\n\t\t\tBackgroundColor3 = bg or T.surface,\n\t\t\tBackgroundTransparency = bg == false and 1 or 0,\n\t\t\tAutoButtonColor = false, BorderSizePixel = 0, Image = "", ZIndex = 9, Parent = parent,\n\t\t}, { corner(5) })\n\t\tstroke(T.line, 1, 0.55).Parent = b\n\t\tnew("ImageLabel", {\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),\n\t\t\tSize = UDim2.fromOffset(12, 12), BackgroundTransparency = 1,\n\t\t\tImage = image, ImageColor3 = tint or T.text2, ZIndex = 10, Parent = b,\n\t\t})\n\t\treturn b\n\tend\n\n\tlocal function rowFrame(parent, height, order)\n\t\treturn new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, height), BackgroundTransparency = 1,\n\t\t\tLayoutOrder = order, ZIndex = 8, Parent = parent,\n\t\t})\n\tend\n\n\tlocal function label(parent, text, size, pos, ts, col, font, align)\n\t\treturn new("TextLabel", {\n\t\t\tSize = size, Position = pos or UDim2.new(), BackgroundTransparency = 1,\n\t\t\tText = text, TextColor3 = col or T.text1, TextSize = ts or 10,\n\t\t\tFont = font or Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = align or Enum.TextXAlignment.Left,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 8, Parent = parent,\n\t\t})\n\tend\n\n\tlocal function sectionLabel(parent, text, order)\n\t\tlocal l = label(parent, string.upper(text), UDim2.new(1, 0, 0, 12), nil, 8, T.text3, Enum.Font.BuilderSansBold)\n\t\tl.LayoutOrder = order\n\t\treturn l\n\tend\n\n\tlocal function listenForKey(btn, onKey)\n\t\tif isSettingBind then return end\n\t\tisSettingBind = true\n\t\tbtn.Text = "..."\n\t\tlocal conn\n\t\tconn = userInputService.InputBegan:Connect(function(input)\n\t\t\tif input.UserInputType ~= Enum.UserInputType.Keyboard then return end\n\t\t\tconn:Disconnect()\n\t\t\ttask.defer(function() isSettingBind = false end)\n\t\t\tif input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then\n\t\t\t\tonKey(nil)\n\t\t\telse\n\t\t\t\tonKey(input.KeyCode)\n\t\t\tend\n\t\tend)\n\t\ttask.delay(8, function()\n\t\t\tif conn and conn.Connected then\n\t\t\t\tconn:Disconnect()\n\t\t\t\tisSettingBind = false\n\t\t\t\tonKey(false)\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function previewDraft()\n\t\tlocal st = _G.LumenSeqState\n\t\tif st.playing and st.seq == draft then\n\t\t\t_G.stopCombinedSequence()\n\t\t\treturn\n\t\tend\n\t\tlocal ok, err = _G.playCombinedSequence(draft)\n\t\tif not ok then setStatus(err, T.danger) else setStatus("Previewing sequence...", T.accent) end\n\t\trefreshCombinePanel()\n\tend\n\n\tlocal function saveDraft()\n\t\tif #draft.clips == 0 then setStatus("Add at least one animation first", T.danger); refreshCombinePanel(); return end\n\t\tlocal name = (draft.name or ""):match("^%s*(.-)%s*$")\n\t\tif name == "" then name = "Sequence " .. (#_G.combinedSequences + 1) end\n\t\tlocal clips = {}\n\t\tfor _, c in ipairs(draft.clips) do\n\t\t\ttable.insert(clips, { anim = c.anim, start = c.start, stop = c.stop, speed = c.speed })\n\t\tend\n\t\tif editingIndex and _G.combinedSequences[editingIndex] then\n\t\t\tlocal seq = _G.combinedSequences[editingIndex]\n\t\t\tseq.name, seq.clips, seq.loop = name, clips, draft.loop\n\t\telse\n\t\t\ttable.insert(_G.combinedSequences, { name = name, loop = draft.loop, clips = clips })\n\t\tend\n\t\tpcall(saveCombinedSequences)\n\t\tdraft.name, draft.clips, draft.loop = "", {}, false\n\t\teditingIndex = nil\n\t\tsetStatus("Saved \\"" .. name .. "\\" - bind a key below", Color3.fromRGB(80, 220, 120))\n\t\trefreshCombinePanel()\n\tend\n\n\trefreshCombinePanel = function()\n\t\tfor _, child in ipairs(combinePanelFrame:GetChildren()) do\n\t\t\tif child:IsA("GuiObject") then child:Destroy() end\n\t\tend\n\t\tlocal st = _G.LumenSeqState\n\n\t\t-- \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500} Builder card \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\n\t\tlocal builder = card(1)\n\t\tlocal order = 0\n\t\tlocal function nextOrder() order = order + 1; return order end\n\n\t\tlocal head = rowFrame(builder, 16, nextOrder())\n\t\tlabel(head, editingIndex and "Editing Sequence" or "Sequence Builder", UDim2.new(0.6, 0, 1, 0), nil, 11)\n\t\tlabel(head, "Total " .. fmtTime(seqTotal(draft.clips)), UDim2.new(0.4, 0, 1, 0), UDim2.new(0.6, 0, 0, 0), 9.5, T.accent2, nil, Enum.TextXAlignment.Right)\n\n\t\tlocal nameRow = rowFrame(builder, 22, nextOrder())\n\t\tlocal nameBox = makeBox(nameRow, draft.name or "", UDim2.new(1, -68, 1, 0), UDim2.new(), "Sequence name")\n\t\tnameBox.FocusLost:Connect(function() draft.name = nameBox.Text end)\n\t\tlocal loopBtn = makeBtn(nameRow, draft.loop and "Loop: ON" or "Loop: OFF", UDim2.fromOffset(62, 22), UDim2.new(1, -62, 0, 0),\n\t\t\tdraft.loop and Color3.fromRGB(255, 255, 255) or T.surface3, draft.loop and Color3.fromRGB(15, 15, 20) or T.text2)\n\t\tloopBtn.MouseButton1Click:Connect(function()\n\t\t\tdraft.name = nameBox.Text\n\t\t\tdraft.loop = not draft.loop\n\t\t\trefreshCombinePanel()\n\t\tend)\n\n\t\tsectionLabel(builder, "Add animation  -  all + customs", nextOrder())\n\t\tlocal searchRow = rowFrame(builder, 22, nextOrder())\n\t\tlocal search = makeBox(searchRow, pickerFilter, UDim2.new(1, 0, 1, 0), UDim2.new(), "Search all animations...")\n\t\tlocal list = new("ScrollingFrame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 110), LayoutOrder = nextOrder(),\n\t\t\tBackgroundColor3 = T.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,\n\t\t\tScrollBarThickness = 0, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(),\n\t\t\tZIndex = 8, Parent = builder,\n\t\t}, { corner(6), pad(3, 3, 3, 3) })\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list })\n\t\tlocal function fillList()\n\t\t\tfor _, c in ipairs(list:GetChildren()) do\n\t\t\t\tif c:IsA("GuiObject") then c:Destroy() end\n\t\t\tend\n\t\t\tlocal f = pickerFilter:lower()\n\t\t\tlocal shown = 0\n\t\t\tfor _, name in ipairs(getAllAnimNames()) do\n\t\t\t\tif f == "" or name:lower():find(f, 1, true) then\n\t\t\t\t\tshown = shown + 1\n\t\t\t\t\tif shown > 150 then break end\n\t\t\t\t\tlocal row = new("TextButton", {\n\t\t\t\t\t\tSize = UDim2.new(1, 0, 0, 26), LayoutOrder = shown,\n\t\t\t\t\t\tBackgroundColor3 = T.surface2, BackgroundTransparency = 0.25,\n\t\t\t\t\t\tText = (name:sub(-4):lower() == ".lua") and name:sub(1, -5) or name,\n\t\t\t\t\t\tTextColor3 = T.text1, TextSize = 10, Font = Enum.Font.BuilderSansMedium,\n\t\t\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\t\t\t\tAutoButtonColor = false, BorderSizePixel = 0, ZIndex = 9, Parent = list,\n\t\t\t\t\t}, { corner(6), pad(0, 26, 0, 9) })\n\t\t\t\t\tnew("TextLabel", {\n\t\t\t\t\t\tAnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 20, 0.5, 0),\n\t\t\t\t\t\tSize = UDim2.fromOffset(14, 14), BackgroundTransparency = 1,\n\t\t\t\t\t\tText = "+", TextColor3 = T.text3, TextSize = 14, Font = Enum.Font.BuilderSansBold, ZIndex = 10, Parent = row,\n\t\t\t\t\t})\n\t\t\t\t\trow.MouseButton1Click:Connect(function()\n\t\t\t\t\t\tdraft.name = nameBox.Text\n\t\t\t\t\t\ttable.insert(draft.clips, { anim = name, start = 0, stop = _G.LumenSeqDuration(name), speed = 1 })\n\t\t\t\t\t\tsetStatus("Added " .. name, T.text2)\n\t\t\t\t\t\trefreshCombinePanel()\n\t\t\t\t\tend)\n\t\t\t\tend\n\t\t\tend\n\t\t\tif shown == 0 then\n\t\t\t\tlocal e = label(list, "No animations found", UDim2.new(1, 0, 0, 22), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\t\te.LayoutOrder = 1\n\t\t\tend\n\t\tend\n\t\tfillList()\n\t\tsearch:GetPropertyChangedSignal("Text"):Connect(function()\n\t\t\tpickerFilter = search.Text\n\t\t\tfillList()\n\t\tend)\n\n\t\tsectionLabel(builder, "Sequence  -  trim and speed per clip", nextOrder())\n\t\tlocal clipsBox = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,\n\t\t\tBackgroundTransparency = 1, LayoutOrder = nextOrder(), ZIndex = 8, Parent = builder,\n\t\t})\n\t\tnew("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = clipsBox })\n\t\tif #draft.clips == 0 then\n\t\t\tlocal e = label(clipsBox, "Pick animations above to build your sequence", UDim2.new(1, 0, 0, 24), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\te.LayoutOrder = 1\n\t\tend\n\t\tfor i, clip in ipairs(draft.clips) do\n\t\t\tlocal row = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 74), LayoutOrder = i,\n\t\t\t\tBackgroundColor3 = T.surface3, BackgroundTransparency = 0.35, BorderSizePixel = 0,\n\t\t\t\tZIndex = 8, Parent = clipsBox,\n\t\t\t}, { corner(8), pad(7, 8, 7, 8) })\n\t\t\tstroke(T.line, 1, 0.5).Parent = row\n\t\t\tlocal active = st.playing and st.seq == draft and st.index == i\n\t\t\tlocal shownName = (clip.anim:sub(-4):lower() == ".lua") and clip.anim:sub(1, -5) or clip.anim\n\t\t\tlocal badge = new("TextLabel", {\n\t\t\t\tSize = UDim2.fromOffset(18, 18), BackgroundColor3 = active and Color3.fromRGB(255, 255, 255) or T.surface,\n\t\t\t\tText = tostring(i), TextColor3 = active and Color3.fromRGB(15, 15, 20) or T.text2,\n\t\t\t\tTextSize = 9, Font = Enum.Font.BuilderSansBold, BorderSizePixel = 0, ZIndex = 9, Parent = row,\n\t\t\t}, { corner(9) })\n\t\t\tlabel(row, shownName, UDim2.new(1, -92, 0, 18), UDim2.fromOffset(25, 0), 10, active and T.accent or T.text1, Enum.Font.BuilderSansMedium)\n\t\t\tlocal up = iconBtn(row, upIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -66, 0, 0))\n\t\t\tlocal dn = iconBtn(row, downIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -44, 0, 0))\n\t\t\tlocal rm = iconBtn(row, delIconId, UDim2.fromOffset(20, 18), UDim2.new(1, -22, 0, 0), T.danger, Color3.fromRGB(38, 20, 24))\n\t\t\tup.MouseButton1Click:Connect(function()\n\t\t\t\tif i > 1 then draft.clips[i], draft.clips[i - 1] = draft.clips[i - 1], draft.clips[i]; draft.name = nameBox.Text; refreshCombinePanel() end\n\t\t\tend)\n\t\t\tdn.MouseButton1Click:Connect(function()\n\t\t\t\tif i < #draft.clips then draft.clips[i], draft.clips[i + 1] = draft.clips[i + 1], draft.clips[i]; draft.name = nameBox.Text; refreshCombinePanel() end\n\t\t\tend)\n\t\t\trm.MouseButton1Click:Connect(function()\n\t\t\t\ttable.remove(draft.clips, i); draft.name = nameBox.Text; refreshCombinePanel()\n\t\t\tend)\n\t\t\tlocal dur = _G.LumenSeqDuration(clip.anim)\n\t\t\tlocal function field(title, x, value, commit)\n\t\t\t\tlabel(row, title, UDim2.new(0.32, 0, 0, 10), UDim2.new(x, 0, 0, 22), 7.5, T.text3, Enum.Font.BuilderSansMedium)\n\t\t\t\tlocal tb = makeBox(row, value, UDim2.new(0.32, -4, 0, 20), UDim2.new(x, 0, 0, 33))\n\t\t\t\ttb.TextXAlignment = Enum.TextXAlignment.Center\n\t\t\t\ttb.FocusLost:Connect(function()\n\t\t\t\t\tlocal n = tonumber(tb.Text)\n\t\t\t\t\tif n then commit(n) end\n\t\t\t\t\trefreshCombinePanel()\n\t\t\t\tend)\n\t\t\tend\n\t\t\tfield("START (s)", 0, string.format("%.2f", clip.start), function(n)\n\t\t\t\tclip.start = math.clamp(n, 0, math.max(0, clip.stop - 0.05))\n\t\t\tend)\n\t\t\tfield("END (s)  /" .. string.format("%.1f", dur), 0.34, string.format("%.2f", clip.stop), function(n)\n\t\t\t\tclip.stop = math.clamp(n, clip.start + 0.05, math.max(dur, clip.start + 0.05))\n\t\t\tend)\n\t\t\tfield("SPEED (x)", 0.68, string.format("%.2f", clip.speed), function(n)\n\t\t\t\tclip.speed = math.clamp(n, 0.1, 5)\n\t\t\tend)\n\t\t\t-- mini timeline: bright part = the portion of the animation that plays\n\t\t\tlocal track = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 3), Position = UDim2.new(0, 0, 1, -3),\n\t\t\t\tBackgroundColor3 = T.surface, BorderSizePixel = 0, ZIndex = 9, Parent = row,\n\t\t\t}, { corner(2) })\n\t\t\tlocal f0 = math.clamp(clip.start / math.max(dur, 0.01), 0, 1)\n\t\t\tlocal f1 = math.clamp(clip.stop / math.max(dur, 0.01), f0, 1)\n\t\t\tnew("Frame", {\n\t\t\t\tPosition = UDim2.fromScale(f0, 0), Size = UDim2.fromScale(math.max(f1 - f0, 0.01), 1),\n\t\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, ZIndex = 10, Parent = track,\n\t\t\t}, { corner(2) })\n\t\tend\n\n\t\tlocal act = rowFrame(builder, 24, nextOrder())\n\t\tnew("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = act })\n\t\tlocal playing = st.playing and st.seq == draft\n\t\tlocal prev = makeBtn(act, playing and "Stop" or "Preview", UDim2.new(0.34, -3, 1, 0), nil,\n\t\t\tplaying and Color3.fromRGB(40, 40, 45) or T.surface3, T.accent2, T.accent2)\n\t\tprev.LayoutOrder = 1\n\t\tlocal save = makeBtn(act, editingIndex and "Update" or "Save", UDim2.new(0.34, -3, 1, 0), nil,\n\t\t\tColor3.fromRGB(255, 255, 255), Color3.fromRGB(15, 15, 20))\n\t\tsave.LayoutOrder = 2\n\t\tlocal clr = makeBtn(act, editingIndex and "Cancel" or "Clear", UDim2.new(0.32, -2, 1, 0), nil, T.surface3, T.danger, T.danger)\n\t\tclr.LayoutOrder = 3\n\t\tprev.MouseButton1Click:Connect(function() draft.name = nameBox.Text; previewDraft() end)\n\t\tsave.MouseButton1Click:Connect(function() draft.name = nameBox.Text; saveDraft() end)\n\t\tclr.MouseButton1Click:Connect(function()\n\t\t\tif st.playing and st.seq == draft then _G.stopCombinedSequence() end\n\t\t\tdraft.name, draft.clips, draft.loop = "", {}, false\n\t\t\teditingIndex = nil\n\t\t\tsetStatus("", nil)\n\t\t\trefreshCombinePanel()\n\t\tend)\n\t\tlocal stLbl = label(builder, statusText, UDim2.new(1, 0, 0, 14), nil, 8.5, statusColor or T.text3, Enum.Font.BuilderSans)\n\t\tstLbl.LayoutOrder = nextOrder()\n\n\t\t-- \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500} Saved sequences \u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\n\t\tlocal seqs = _G.combinedSequences\n\t\tlocal saved = card(2)\n\t\tlocal h = label(saved, "Saved Sequences", UDim2.new(1, 0, 0, 16), nil, 11.5)\n\t\th.LayoutOrder = 1\n\t\tif #seqs == 0 then\n\t\t\tlocal e = label(saved, "Nothing saved yet", UDim2.new(1, 0, 0, 22), nil, 9, T.text3, Enum.Font.BuilderSans, Enum.TextXAlignment.Center)\n\t\t\te.LayoutOrder = 2\n\t\tend\n\t\tfor idx, seq in ipairs(seqs) do\n\t\t\tlocal isPlaying = st.playing and st.seq == seq\n\t\t\tlocal row = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 64), LayoutOrder = 1 + idx,\n\t\t\t\tBackgroundColor3 = T.surface3, BackgroundTransparency = 0.3, BorderSizePixel = 0,\n\t\t\t\tZIndex = 8, Parent = saved,\n\t\t\t}, { corner(6), pad(6, 8, 6, 8) })\n\t\t\tstroke(T.line, 1, 0.5).Parent = row\n\t\t\tlabel(row, seq.name, UDim2.new(1, 0, 0, 14), UDim2.fromOffset(0, 0), 10, isPlaying and T.accent or T.text1)\n\t\t\tlabel(row, string.format("%d clips - %s%s", #seq.clips, fmtTime(seqTotal(seq.clips)), seq.loop and " - loop" or ""),\n\t\t\t\tUDim2.new(1, 0, 0, 11), UDim2.fromOffset(0, 15), 8, T.text3, Enum.Font.BuilderSans)\n\t\t\tlocal btns = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 22), Position = UDim2.new(0, 0, 1, -22),\n\t\t\t\tBackgroundTransparency = 1, ZIndex = 8, Parent = row,\n\t\t\t})\n\t\t\tnew("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = btns })\n\t\t\tlocal play = makeBtn(btns, isPlaying and "Stop" or "Play", UDim2.new(0.22, -3, 1, 0), nil,\n\t\t\t\tisPlaying and Color3.fromRGB(40, 40, 45) or Color3.fromRGB(255, 255, 255), isPlaying and T.text1 or Color3.fromRGB(15, 15, 20))\n\t\t\tplay.LayoutOrder = 1\n\t\t\tlocal keyBtn = makeBtn(btns, seq.key and seq.key.Name or "Bind key", UDim2.new(0.3, -3, 1, 0), nil,\n\t\t\t\tT.surface, seq.key and T.accent or T.text2)\n\t\t\tkeyBtn.LayoutOrder = 2\n\t\t\tlocal edit = makeBtn(btns, "Edit", UDim2.new(0.22, -3, 1, 0))\n\t\t\tedit.LayoutOrder = 3\n\t\t\tlocal del = iconBtn(btns, delIconId, UDim2.new(0.26, -3, 1, 0), nil, T.danger, Color3.fromRGB(38, 20, 24))\n\t\t\tdel.LayoutOrder = 4\n\t\t\tplay.MouseButton1Click:Connect(function()\n\t\t\t\tif isPlaying then\n\t\t\t\t\t_G.stopCombinedSequence()\n\t\t\t\telse\n\t\t\t\t\tlocal ok, err = _G.playCombinedSequence(seq)\n\t\t\t\t\tsetStatus(ok and "" or err, ok and nil or T.danger)\n\t\t\t\tend\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\t\tkeyBtn.MouseButton1Click:Connect(function()\n\t\t\t\tlistenForKey(keyBtn, function(k)\n\t\t\t\t\tif k == false then refreshCombinePanel(); return end\n\t\t\t\t\tif k then\n\t\t\t\t\t\tfor _, other in ipairs(_G.combinedSequences) do\n\t\t\t\t\t\t\tif other ~= seq and other.key == k then other.key = nil end\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tseq.key = k\n\t\t\t\t\tpcall(saveCombinedSequences)\n\t\t\t\t\trefreshCombinePanel()\n\t\t\t\tend)\n\t\t\tend)\n\t\t\tedit.MouseButton1Click:Connect(function()\n\t\t\t\tdraft.name, draft.loop, draft.clips = seq.name, seq.loop == true, {}\n\t\t\t\tfor _, c in ipairs(seq.clips) do\n\t\t\t\t\ttable.insert(draft.clips, { anim = c.anim, start = c.start, stop = c.stop, speed = c.speed })\n\t\t\t\tend\n\t\t\t\teditingIndex = idx\n\t\t\t\tsetStatus("Editing \\"" .. seq.name .. "\\"", T.text2)\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\t\tdel.MouseButton1Click:Connect(function()\n\t\t\t\tif st.playing and st.seq == seq then _G.stopCombinedSequence() end\n\t\t\t\ttable.remove(_G.combinedSequences, idx)\n\t\t\t\tif editingIndex == idx then editingIndex = nil end\n\t\t\t\tpcall(saveCombinedSequences)\n\t\t\t\trefreshCombinePanel()\n\t\t\tend)\n\t\tend\n\tend\n\n\t-- keep the panel in sync as the sequence advances / ends (only while visible)\n\tlocal lastSeqSig = ""\n\t_G.LumenSeqOnChange = function()\n\t\ttask.defer(function()\n\t\t\tif combinePanelFrame and combinePanelFrame.Parent and combinePanelFrame.Visible then\n\t\t\t\tlocal st = _G.LumenSeqState\n\t\t\t\tlocal sig = tostring(st.playing) .. tostring(st.index) .. tostring(st.seq)\n\t\t\t\tif sig ~= lastSeqSig then\n\t\t\t\t\tlastSeqSig = sig\n\t\t\t\t\tif not userInputService:GetFocusedTextBox() then\n\t\t\t\t\t\tpcall(refreshCombinePanel)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\n\tpcall(loadCombinedSequences)\n\trefreshCombinePanel()\n\n\tend\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- RECORD TAB: SELF PLAYER ANIMATION RECORDER\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\tlocal isRecordingAnim = false\n\tlocal recordedFrames = {}\n\tlocal recordStartTime = 0\n\tlocal recordLoopConn = nil\n\tlocal recordStatusLabel\n\tlocal recordTimerLabel\n\tlocal recToggleBtn\n\tlocal recSaveBtn\n\tlocal recPrevBtn\n\tlocal recNameInput\n\n\tlocal function getTargetRecordingCharacter()\n\t\tlocal clone = (lumenAPI and lumenAPI.get_clone) and lumenAPI.get_clone(localPlayer)\n\t\tif clone and clone:FindFirstChild("HumanoidRootPart") then\n\t\t\treturn clone\n\t\tend\n\t\tif localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart") then\n\t\t\treturn localPlayer.Character\n\t\tend\n\t\treturn nil\n\tend\n\n\tlocal function captureFramePose(targetChar)\n\t\tif not targetChar then return nil end\n\t\tlocal frameData = {}\n\t\tlocal joints = {}\n\n\t\tfor _, desc in ipairs(targetChar:GetDescendants()) do\n\t\t\tif desc:IsA("Motor6D") and desc.Enabled and desc.Part0 and desc.Part1 then\n\t\t\t\tlocal p1Name = desc.Part1.Name\n\t\t\t\tif p1Name ~= "HumanoidRootPart" then\n\t\t\t\t\tlocal cf = desc.Transform or CFrame.identity\n\t\t\t\t\tframeData[p1Name] = cf\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\tif next(frameData) == nil then\n\t\t\tlocal hrp = targetChar:FindFirstChild("HumanoidRootPart")\n\t\t\tif hrp then\n\t\t\t\tfor _, pName in ipairs({"Head", "Torso", "UpperTorso", "LowerTorso", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "RightUpperArm", "LeftUpperArm", "RightLowerArm", "LeftLowerArm", "RightHand", "LeftHand", "RightUpperLeg", "LeftUpperLeg", "RightLowerLeg", "LeftLowerLeg", "RightFoot", "LeftFoot"}) do\n\t\t\t\t\tlocal part = targetChar:FindFirstChild(pName)\n\t\t\t\t\tif part and part:IsA("BasePart") then\n\t\t\t\t\t\tframeData[pName] = hrp.CFrame:ToObjectSpace(part.CFrame)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\treturn frameData\n\tend\n\n\tlocal function buildRecordedLua(frames)\n\t\tlocal lines = { "return {" }\n\t\tfor _, kf in ipairs(frames) do\n\t\t\ttable.insert(lines, "        {")\n\t\t\ttable.insert(lines, string.format("            Time = %.4f,", kf.Time))\n\t\t\ttable.insert(lines, "            Data = {")\n\t\t\tfor partName, cf in pairs(kf.Data) do\n\t\t\t\tlocal x, y, z, R00, R01, R02, R10, R11, R12, R20, R21, R22 = cf:GetComponents()\n\t\t\t\tlocal cfStr = string.format("CFrame.new(%.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f, %.4f)",\n\t\t\t\t\tx, y, z, R00, R01, R02, R10, R11, R12, R20, R21, R22)\n\t\t\t\ttable.insert(lines, string.format("                [\\"%s\\"] = %s,", partName, cfStr))\n\t\t\tend\n\t\t\ttable.insert(lines, "            }")\n\t\t\ttable.insert(lines, "        },")\n\t\tend\n\t\ttable.insert(lines, "}")\n\t\treturn table.concat(lines, "\\n")\n\tend\n\n\tlocal function stopRecordingAnim()\n\t\tif not isRecordingAnim then return end\n\t\tisRecordingAnim = false\n\t\tif recordLoopConn then\n\t\t\trecordLoopConn:Disconnect()\n\t\t\trecordLoopConn = nil\n\t\tend\n\t\tlocal duration = tick() - recordStartTime\n\t\tif recordStatusLabel then\n\t\t\trecordStatusLabel.Text = string.format("Recorded %d keyframes (%.2fs)", #recordedFrames, duration)\n\t\t\trecordStatusLabel.TextColor3 = T.text1\n\t\tend\n\t\tif recToggleBtn then\n\t\t\trecToggleBtn.Text = "\u{25cf} Record"\n\t\t\trecToggleBtn.BackgroundColor3 = Color3.fromRGB(220, 50, 60)\n\t\tend\n\t\tif recSaveBtn then\n\t\t\trecSaveBtn.Visible = (#recordedFrames > 0)\n\t\tend\n\t\tif recPrevBtn then\n\t\t\trecPrevBtn.Visible = (#recordedFrames > 0)\n\t\tend\n\tend\n\n\tlocal function startRecordingAnim()\n\t\tif isRecordingAnim then return end\n\t\tlocal targetChar = getTargetRecordingCharacter()\n\t\tif not targetChar then\n\t\t\tif recordStatusLabel then\n\t\t\t\trecordStatusLabel.Text = "Error: Character not found!"\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\tend\n\t\t\treturn\n\t\tend\n\n\t\trecordedFrames = {}\n\t\trecordStartTime = tick()\n\t\tisRecordingAnim = true\n\n\t\tif recToggleBtn then\n\t\t\trecToggleBtn.Text = "\u{25a0} Stop Recording"\n\t\t\trecToggleBtn.BackgroundColor3 = Color3.fromRGB(40, 40, 45)\n\t\tend\n\t\tif recordStatusLabel then\n\t\t\trecordStatusLabel.Text = "Recording player pose @ 30 FPS..."\n\t\t\trecordStatusLabel.TextColor3 = T.accent\n\t\tend\n\t\tif recSaveBtn then recSaveBtn.Visible = false end\n\t\tif recPrevBtn then recPrevBtn.Visible = false end\n\n\t\tlocal lastSample = 0\n\t\tlocal sampleInterval = 1 / 30\n\n\t\trecordLoopConn = runService.Heartbeat:Connect(function()\n\t\t\tLPS_ATTRIBUTES(VM(NONE))\n\t\t\tif not isRecordingAnim then return end\n\t\t\tlocal now = tick()\n\t\t\tlocal elapsed = now - recordStartTime\n\t\t\tif recordTimerLabel then\n\t\t\t\trecordTimerLabel.Text = string.format("%02d:%04.1f", math.floor(elapsed / 60), elapsed % 60)\n\t\t\tend\n\t\t\tif (now - lastSample) >= sampleInterval then\n\t\t\t\tlastSample = now\n\t\t\t\tlocal char = getTargetRecordingCharacter()\n\t\t\t\tif char then\n\t\t\t\t\tlocal data = captureFramePose(char)\n\t\t\t\t\tif data and next(data) ~= nil then\n\t\t\t\t\t\ttable.insert(recordedFrames, {\n\t\t\t\t\t\t\tTime = elapsed,\n\t\t\t\t\t\t\tData = data\n\t\t\t\t\t\t})\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function refreshRecordPanel()\n\t\tfor _, child in ipairs(recordPanelFrame:GetChildren()) do\n\t\t\tif child:IsA("GuiObject") and not child:IsA("UIListLayout") and not child:IsA("UIPadding") then\n\t\t\t\tchild:Destroy()\n\t\t\tend\n\t\tend\n\n\t\tlocal card = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 236),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = recordPanelFrame,\n\t\t}, { corner(8), pad(0, 12, 0, 12) })\n\t\tstroke(T.line, 1, 0.4).Parent = card\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 18),\n\t\t\tPosition = UDim2.fromOffset(0, 10),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Animation Recorder",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 12,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = card,\n\t\t})\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 14),\n\t\t\tPosition = UDim2.fromOffset(0, 30),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Record your pose, preview it, save to customs",\n\t\t\tTextColor3 = T.text3,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSans,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecordTimerLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\t\tPosition = UDim2.fromOffset(0, 52),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "00:00.0",\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 24,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Center,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecordStatusLabel = new("TextLabel", {\n\t\t\tSize = UDim2.new(1, 0, 0, 16),\n\t\t\tPosition = UDim2.fromOffset(0, 92),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Ready to record",\n\t\t\tTextColor3 = T.text2,\n\t\t\tTextSize = 9.5,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Center,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecToggleBtn = new("TextButton", {\n\t\t\tSize = UDim2.new(1, 0, 0, 32),\n\t\t\tPosition = UDim2.new(0, 0, 0, 114),\n\t\t\tBackgroundColor3 = Color3.fromRGB(220, 50, 60),\n\t\t\tText = isRecordingAnim and "\u{25a0} Stop Recording" or "\u{25cf} Record",\n\t\t\tTextColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tTextSize = 10.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = card,\n\t\t}, { corner(6) })\n\t\trecToggleBtn.MouseButton1Click:Connect(function()\n\t\t\tif isRecordingAnim then\n\t\t\t\tstopRecordingAnim()\n\t\t\telse\n\t\t\t\tstartRecordingAnim()\n\t\t\tend\n\t\tend)\n\n\t\trecNameInput = new("TextBox", {\n\t\t\tSize = UDim2.new(1, 0, 0, 26),\n\t\t\tPosition = UDim2.new(0, 0, 0, 154),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tTextColor3 = T.text1,\n\t\t\tPlaceholderText = "Animation name (e.g. MyRecordedAnim)...",\n\t\t\tPlaceholderColor3 = T.text3,\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tText = "",\n\t\t\tClearTextOnFocus = false,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = card,\n\t\t}, { corner(5), pad(0, 8, 0, 8) })\n\t\tstroke(T.line, 1, 0.5).Parent = recNameInput\n\n\t\tlocal actionsRow = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\tPosition = UDim2.new(0, 0, 0, 188),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tParent = card,\n\t\t})\n\n\t\trecPrevBtn = new("TextButton", {\n\t\t\tSize = UDim2.new(0.48, -4, 1, 0),\n\t\t\tPosition = UDim2.new(0, 0, 0, 0),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tText = "Preview",\n\t\t\tTextColor3 = T.accent2,\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tVisible = (#recordedFrames > 0),\n\t\t\tParent = actionsRow,\n\t\t}, { corner(5) })\n\t\tstroke(T.accent2, 1, 0.4).Parent = recPrevBtn\n\n\t\trecPrevBtn.MouseButton1Click:Connect(function()\n\t\t\tif #recordedFrames == 0 then return end\n\t\t\tif lumenAPI.is_animation_playing and lumenAPI.is_animation_playing() and lumen.animation.state.current_url\n\t\t\t\tand tostring(lumen.animation.state.current_url):sub(1, 8) == "return {" and lumen.animation.state.current_url:find("Time = ", 1, true) then\n\t\t\t\tlumenAPI.stop_animation()\n\t\t\t\trecordStatusLabel.Text = "Preview stopped"\n\t\t\t\trecordStatusLabel.TextColor3 = T.text1\n\t\t\t\treturn\n\t\t\tend\n\t\t\tif not (lumenAPI.is_reanimated and lumenAPI.is_reanimated()) then\n\t\t\t\trecordStatusLabel.Text = "Enable Reanimate first to preview"\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\t\treturn\n\t\t\tend\n\t\t\tlocal animCode = buildRecordedLua(recordedFrames)\n\t\t\tlocal err = lumenAPI.play_animation(animCode, (animationContext and animationContext.speed) or 1)\n\t\t\tif type(err) == "string" then\n\t\t\t\trecordStatusLabel.Text = err\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\telse\n\t\t\t\trecordStatusLabel.Text = "Playing preview (click again to stop)"\n\t\t\t\trecordStatusLabel.TextColor3 = T.accent\n\t\t\tend\n\t\tend)\n\n\t\trecSaveBtn = new("TextButton", {\n\t\t\tSize = UDim2.new(0.48, -4, 1, 0),\n\t\t\tPosition = UDim2.new(0.52, 4, 0, 0),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tText = "",\n\t\t\tTextColor3 = Color3.fromRGB(15, 15, 20),\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tVisible = (#recordedFrames > 0),\n\t\t\tParent = actionsRow,\n\t\t}, { corner(5) })\n\n\t\tlocal saveInner = new("Frame", {\n\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tZIndex = 10,\n\t\t\tParent = recSaveBtn,\n\t\t}, { new("UIListLayout", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\t\tVerticalAlignment = Enum.VerticalAlignment.Center,\n\t\t\tPadding = UDim.new(0, 5),\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t}) })\n\t\tlocal saveIcon = new("ImageLabel", {\n\t\t\tLayoutOrder = 1,\n\t\t\tSize = UDim2.fromOffset(13, 13),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tImage = "rbxthumb://type=Asset&id=87338355970398&w=150&h=150",\n\t\t\tImageColor3 = Color3.fromRGB(15, 15, 20),\n\t\t\tZIndex = 11,\n\t\t\tParent = saveInner,\n\t\t})\n\t\tlocal saveLabel = new("TextLabel", {\n\t\t\tLayoutOrder = 2,\n\t\t\tSize = UDim2.fromOffset(0, 13),\n\t\t\tAutomaticSize = Enum.AutomaticSize.X,\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = "Save to Customs",\n\t\t\tTextColor3 = Color3.fromRGB(15, 15, 20),\n\t\t\tTextSize = 9,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tZIndex = 11,\n\t\t\tParent = saveInner,\n\t\t})\n\t\tlocal function setSaveLabel(t, withIcon)\n\t\t\tsaveLabel.Text = t\n\t\t\tsaveIcon.Visible = withIcon\n\t\tend\n\t\trecSaveBtn.MouseButton1Click:Connect(function()\n\t\t\tif #recordedFrames == 0 then\n\t\t\t\trecordStatusLabel.Text = "No frames to save!"\n\t\t\t\trecordStatusLabel.TextColor3 = T.danger\n\t\t\t\treturn\n\t\t\tend\n\t\t\tlocal name = (recNameInput.Text ~= "") and recNameInput.Text or ("Recorded_" .. tostring(os.date("%H%M%S")))\n\t\t\tlocal sanitized = name:gsub("[^%w%s%-_]", ""):match("^%s*(.-)%s*$")\n\t\t\tif not sanitized or sanitized == "" then sanitized = "Recorded_" .. tostring(tick()):sub(-4) end\n\t\t\tlocal animCode = buildRecordedLua(recordedFrames)\n\t\t\ttransformCache[sanitized] = animCode\n\t\t\tif animationQueue then animationQueue[sanitized] = animCode end\n\t\t\tpcall(function()\n\t\t\t\tif not isfolder(customsFolderPath) then makefolder(customsFolderPath) end\n\t\t\t\tif writefile then\n\t\t\t\t\twritefile(customsFolderPath .. "/" .. sanitized .. ".lua", animCode)\n\t\t\t\tend\n\t\t\tend)\n\t\t\trecordStatusLabel.Text = "Saved: " .. sanitized .. ".lua"\n\t\t\trecordStatusLabel.TextColor3 = Color3.fromRGB(80, 220, 120)\n\t\t\tsetSaveLabel("Saved!", false)\n\t\t\ttask.delay(1.5, function()\n\t\t\t\tsetSaveLabel("Save to Customs", true)\n\t\t\tend)\n\t\t\tinitializeGui()\n\t\t\tif characterModel4 == "custom" then pcall(loadGUI) end\n\t\tend)\n\tend\n\trefreshRecordPanel()\n\tend\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- STATES TAB ROW BUILDER\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- The picker used to destroy and rebuild a row for every animation each time it opened, all in one frame.\n\t-- Rows are now built once, a few per frame, and reused; only the click target changes between opens.\n\tlocal modalState = { name = nil, callback = nil }\n\tlocal modalRows = {}\n\tlocal modalRowsSig = nil\n\tlocal modalBuildToken = 0\n\tlocal noneRow = nil\n\n\tlocal function filterModalRows()\n\t\tlocal query = modalSearch.Text:lower()\n\t\tfor name, row in pairs(modalRows) do\n\t\t\tlocal vis = (query == "") or (row:GetAttribute("lname"):find(query, 1, true) ~= nil)\n\t\t\tif row.Visible ~= vis then row.Visible = vis end\n\t\tend\n\tend\n\tmodalSearch:GetPropertyChangedSignal("Text"):Connect(filterModalRows)\n\n\tlocal function pickAnimation(name)\n\t\tlocal stateName = modalState.name\n\t\tif not stateName then return end\n\t\tlocal targetId = animationQueue[name] or transformCache[name] or characterAttachments[name] or name\n\t\tstateAnimations[stateName] = targetId\n\t\tstateAnimations[tostring(stateName):lower()] = targetId\n\t\tpcall(saveStateAnimations)\n\t\tselectModal.Visible = false\n\t\tif isInitialized and animationFolder then pcall(stateCheckFunction) end\n\t\tif modalState.callback then modalState.callback(name) end\n\tend\n\n\tlocal function ensureModalRows()\n\t\tif not noneRow then\n\t\t\tnoneRow = new("Frame", {\n\t\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\t\tBackgroundColor3 = Color3.fromRGB(35, 20, 25),\n\t\t\t\tBorderSizePixel = 0,\n\t\t\t\tLayoutOrder = -1,\n\t\t\t\tParent = modalScroll,\n\t\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\t\t\tstroke(T.danger, 1, 0.7).Parent = noneRow\n\t\t\tlocal noneBtn = new("TextButton", {\n\t\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\tText = "None (Remove)",\n\t\t\t\tTextColor3 = T.danger,\n\t\t\t\tTextSize = 10,\n\t\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\t\tParent = noneRow,\n\t\t\t})\n\t\t\tnoneBtn.MouseButton1Click:Connect(function()\n\t\t\t\tlocal stateName = modalState.name\n\t\t\t\tif not stateName then return end\n\t\t\t\tstateAnimations[stateName] = nil\n\t\t\t\tstateAnimations[tostring(stateName):lower()] = nil\n\t\t\t\tpcall(saveStateAnimations)\n\t\t\t\tselectModal.Visible = false\n\t\t\t\tif isInitialized and animationFolder then pcall(stateCheckFunction) end\n\t\t\t\tif modalState.callback then modalState.callback("None (Click to select)") end\n\t\t\tend)\n\t\tend\n\n\t\tlocal allAnims = getAllAnimNames and getAllAnimNames() or {}\n\t\tlocal sig = table.concat(allAnims, "\\0")\n\t\tif sig == modalRowsSig then return end\n\t\tmodalRowsSig = sig\n\t\tmodalBuildToken += 1\n\t\tlocal mine = modalBuildToken\n\t\tfor _, r in pairs(modalRows) do pcall(function() r:Destroy() end) end\n\t\tmodalRows = {}\n\t\ttask.spawn(function()\n\t\t\tfor i, name in ipairs(allAnims) do\n\t\t\t\tif mine ~= modalBuildToken then return end\n\t\t\t\tlocal row = new("Frame", {\n\t\t\t\t\tSize = UDim2.new(1, 0, 0, 28),\n\t\t\t\t\tBackgroundColor3 = T.surface2,\n\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\tLayoutOrder = i,\n\t\t\t\t\tParent = modalScroll,\n\t\t\t\t}, { corner(6), pad(0, 8, 0, 8) })\n\t\t\t\trow:SetAttribute("lname", name:lower())\n\t\t\t\tstroke(T.line, 1, 0.6).Parent = row\n\t\t\t\tlocal btn = new("TextButton", {\n\t\t\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\t\tText = name,\n\t\t\t\t\tTextColor3 = T.text1,\n\t\t\t\t\tTextSize = 10,\n\t\t\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\t\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\t\t\tParent = row,\n\t\t\t\t})\n\t\t\t\tbtn.MouseButton1Click:Connect(function() pickAnimation(name) end)\n\t\t\t\tmodalRows[name] = row\n\t\t\t\tif modalSearch.Text ~= "" and not name:lower():find(modalSearch.Text:lower(), 1, true) then\n\t\t\t\t\trow.Visible = false\n\t\t\t\tend\n\t\t\t\tif i % 15 == 0 then task.wait() end\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function openSelectionModal(stateName, callback)\n\t\tmodalState.name, modalState.callback = stateName, callback\n\t\tselectModal.Visible = true\n\t\tmodalTitle.Text = "Select " .. stateName:sub(1,1):upper() .. stateName:sub(2) .. " Anim"\n\t\tmodalSearch.Text = ""\n\t\tensureModalRows()\n\t\tfilterModalRows()\n\tend\n\n\tlocal function createStateRow(stateName, labelText)\n\t\tlocal row = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 48),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = statesPanelFrame,\n\t\t}, { corner(8), pad(0, 10, 0, 10) })\n\t\tstroke(T.line, 1, 0.4).Parent = row\n\n\t\tnew("TextLabel", {\n\t\t\tSize = UDim2.new(0.38, 0, 1, 0),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = labelText,\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 10.5,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = row,\n\t\t})\n\n\t\tlocal selectBtn = new("TextButton", {\n\t\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\t\tPosition = UDim2.new(1, 0, 0.5, 0),\n\t\t\tSize = UDim2.new(0.58, 0, 0, 26),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tTextColor3 = T.text2,\n\t\t\tText = "Click to select...",\n\t\t\tTextSize = 9.5,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = row,\n\t\t}, { corner(6) })\n\t\tstroke(T.line, 1, 0.5).Parent = selectBtn\n\n\t\tlocal function refreshText()\n\t\t\tlocal currentVal = stateAnimations[stateName] or stateAnimations[tostring(stateName):lower()]\n\t\t\tif currentVal and currentVal ~= "" then\n\t\t\t\tlocal foundName = nil\n\t\t\t\tfor name, val in pairs(animationQueue) do\n\t\t\t\t\tif tostring(val) == tostring(currentVal) or tostring(val):gsub("%s+", "") == tostring(currentVal):gsub("%s+", "") then\n\t\t\t\t\t\tfoundName = name\n\t\t\t\t\t\tbreak\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tif not foundName then\n\t\t\t\t\tfor name, val in pairs(transformCache) do\n\t\t\t\t\t\tif tostring(val) == tostring(currentVal) or tostring(val):gsub("%s+", "") == tostring(currentVal):gsub("%s+", "") then\n\t\t\t\t\t\t\tfoundName = name\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tif not foundName then\n\t\t\t\t\tfor name, val in pairs(characterAttachments) do\n\t\t\t\t\t\tif tostring(val) == tostring(currentVal) then\n\t\t\t\t\t\t\tfoundName = name\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tselectBtn.Text = foundName or "Custom (" .. (tostring(currentVal):match("rbxassetid://(%d+)") or "Loaded") .. ")"\n\t\t\telse\n\t\t\t\tselectBtn.Text = "None (Click to select)"\n\t\t\tend\n\t\tend\n\n\t\ttask.spawn(function()\n\t\t\ttask.wait(0.5)\n\t\t\trefreshText()\n\t\tend)\n\t\tselectBtn.MouseButton1Click:Connect(function()\n\t\t\topenSelectionModal(stateName, function(selectedName)\n\t\t\t\tselectBtn.Text = selectedName\n\t\t\tend)\n\t\tend)\n\tend\n\tcreateStateRow("idle", "Idle State")\n\tcreateStateRow("walking", "Run/Walk State")\n\tcreateStateRow("jumping", "Jump State")\n\tend\n\tlocal speedCard, sliderBackground, sliderFill, sliderHandle, sliderValueLabel, resetButton3, contentContainer, reverseCard, reverseKeyBtn, revSliderBackground, revSliderFill, revSliderHandle, revSliderValLabel, reverseContentContainer\n\tdo\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- SPEED CONTROLS & SLOTS (Speed Tab)\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\tspeedCard = new("Frame", {\n\t\tSize = UDim2.new(1, 0, 0, 78),\n\t\tBackgroundColor3 = T.surface2,\n\t\tBackgroundTransparency = 0.35,\n\t\tBorderSizePixel = 0,\n\t\tParent = speedsPanelFrame,\n\t}, { corner(8), pad(0, 10, 0, 10) })\n\tstroke(T.line, 1, 0.4).Parent = speedCard\n\n\tnew("TextLabel", {\n\t\tSize = UDim2.fromOffset(50, 20),\n\t\tPosition = UDim2.fromOffset(0, 8),\n\t\tBackgroundTransparency = 1,\n\t\tText = "Speed:",\n\t\tTextColor3 = T.text1,\n\t\tTextSize = 11,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tParent = speedCard,\n\t})\n\n\tsliderBackground = new("Frame", {\n\t\tSize = UDim2.new(1, -120, 0, 12),\n\t\tPosition = UDim2.fromOffset(54, 12),\n\t\tBackgroundColor3 = Color3.fromRGB(22, 22, 28),\n\t\tBorderSizePixel = 0,\n\t\tParent = speedCard,\n\t}, { corner(6) })\n\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.85).Parent = sliderBackground\n\n\tsliderFill = new("Frame", {\n\t\tSize = UDim2.new(0.5, 0, 1, 0),\n\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\tBorderSizePixel = 0,\n\t\tParent = sliderBackground,\n\t}, { corner(6) })\n\tnew("UIGradient", {\n\t\tColor = ColorSequence.new{\n\t\t\tColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),\n\t\t\tColorSequenceKeypoint.new(1, Color3.fromRGB(195, 195, 210)),\n\t\t},\n\t\tTransparency = NumberSequence.new{\n\t\t\tNumberSequenceKeypoint.new(0, 0.85),\n\t\t\tNumberSequenceKeypoint.new(1, 0),\n\t\t},\n\t\tOffset = Vector2.new(0, 0.5),\n\t\tRotation = 2,\n\t\tParent = sliderFill,\n\t})\n\n\tsliderHandle = new("Frame", {\n\t\tSize = UDim2.fromOffset(35, 18),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.new(0.5, 0, 0.5, 0),\n\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\tBorderSizePixel = 0,\n\t\tZIndex = 5,\n\t\tParent = sliderBackground,\n\t}, { corner(9) })\n\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.7).Parent = sliderHandle\n\tpcall(function()\n\t\tlocal glow = Instance.new("ImageLabel")\n\t\tglow.Name = "Glow"\n\t\tglow.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\tglow.Position = UDim2.fromScale(0.5, 0.5)\n\t\tglow.Size = UDim2.new(1, 16, 1, 16)\n\t\tglow.BackgroundTransparency = 1\n\t\tglow.Image = "rbxassetid://6014261993"\n\t\tglow.ImageColor3 = Color3.fromRGB(255, 255, 255)\n\t\tglow.ImageTransparency = 0.55\n\t\tglow.ScaleType = Enum.ScaleType.Slice\n\t\tglow.SliceCenter = Rect.new(49, 49, 450, 450)\n\t\tglow.ZIndex = 4\n\t\tglow.Parent = sliderHandle\n\tend)\n\n\tsliderValueLabel = new("TextLabel", {\n\t\tAnchorPoint = Vector2.new(1, 0),\n\t\tPosition = UDim2.new(1, -44, 0, 8),\n\t\tSize = UDim2.fromOffset(36, 20),\n\t\tBackgroundTransparency = 1,\n\t\tText = "1.0x",\n\t\tTextColor3 = T.text1,\n\t\tTextSize = 10.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Right,\n\t\tParent = speedCard,\n\t})\n\n\tresetButton3 = new("TextButton", {\n\t\tAnchorPoint = Vector2.new(1, 0),\n\t\tPosition = UDim2.new(1, 0, 0, 8),\n\t\tSize = UDim2.fromOffset(38, 20),\n\t\tBackgroundColor3 = T.surface3,\n\t\tText = "Reset",\n\t\tTextColor3 = T.text2,\n\t\tTextSize = 8.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tBorderSizePixel = 0,\n\t\tAutoButtonColor = false,\n\t\tParent = speedCard,\n\t}, { corner(5) })\n\tstroke(T.line, 1, 0.5).Parent = resetButton3\n\n\tcontentContainer = new("Frame", {\n\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\tPosition = UDim2.fromOffset(0, 34),\n\t\tBackgroundTransparency = 1,\n\t\tParent = speedCard,\n\t})\n\n\t-- Hold to Reverse Card\n\treverseCard = new("Frame", {\n\t\tSize = UDim2.new(1, 0, 0, 114),\n\t\tBackgroundColor3 = T.surface2,\n\t\tBackgroundTransparency = 0.35,\n\t\tBorderSizePixel = 0,\n\t\tParent = speedsPanelFrame,\n\t}, { corner(8), pad(0, 10, 0, 10) })\n\tstroke(T.line, 1, 0.4).Parent = reverseCard\n\n\tnew("TextLabel", {\n\t\tSize = UDim2.fromOffset(120, 20),\n\t\tPosition = UDim2.fromOffset(0, 8),\n\t\tBackgroundTransparency = 1,\n\t\tText = "Hold to Reverse",\n\t\tTextColor3 = T.text1,\n\t\tTextSize = 11,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tParent = reverseCard,\n\t})\n\n\treverseKeyBtn = new("TextButton", {\n\t\tAnchorPoint = Vector2.new(1, 0),\n\t\tPosition = UDim2.new(1, 0, 0, 8),\n\t\tSize = UDim2.fromOffset(64, 20),\n\t\tBackgroundColor3 = T.surface3,\n\t\tText = GlobalReverseKey ~= "" and GlobalReverseKey:sub(1,3) or "Key",\n\t\tTextColor3 = GlobalReverseKey ~= "" and T.danger or T.text3,\n\t\tTextSize = 8.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tBorderSizePixel = 0,\n\t\tAutoButtonColor = false,\n\t\tParent = reverseCard,\n\t}, { corner(5) })\n\tstroke(T.line, 1, 0.5).Parent = reverseKeyBtn\n\n\tnew("TextLabel", {\n\t\tSize = UDim2.fromOffset(70, 20),\n\t\tPosition = UDim2.fromOffset(0, 32),\n\t\tBackgroundTransparency = 1,\n\t\tText = "Rev Speed:",\n\t\tTextColor3 = T.text2,\n\t\tTextSize = 9.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tParent = reverseCard,\n\t})\n\n\trevSliderBackground = new("Frame", {\n\t\tSize = UDim2.new(1, -120, 0, 12),\n\t\tPosition = UDim2.fromOffset(74, 36),\n\t\tBackgroundColor3 = Color3.fromRGB(22, 22, 28),\n\t\tBorderSizePixel = 0,\n\t\tParent = reverseCard,\n\t}, { corner(6) })\n\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.85).Parent = revSliderBackground\n\n\trevSliderFill = new("Frame", {\n\t\tSize = UDim2.new(0.33, 0, 1, 0),\n\t\tBackgroundColor3 = T.danger,\n\t\tBorderSizePixel = 0,\n\t\tParent = revSliderBackground,\n\t}, { corner(6) })\n\n\trevSliderHandle = new("Frame", {\n\t\tSize = UDim2.fromOffset(35, 18),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.new(0.33, 0, 0.5, 0),\n\t\tBackgroundColor3 = Color3.fromRGB(255, 255, 255),\n\t\tBorderSizePixel = 0,\n\t\tZIndex = 5,\n\t\tParent = revSliderBackground,\n\t}, { corner(9) })\n\tstroke(Color3.fromRGB(255, 255, 255), 1, 0.7).Parent = revSliderHandle\n\tpcall(function()\n\t\tlocal glow = Instance.new("ImageLabel")\n\t\tglow.Name = "Glow"\n\t\tglow.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\tglow.Position = UDim2.fromScale(0.5, 0.5)\n\t\tglow.Size = UDim2.new(1, 16, 1, 16)\n\t\tglow.BackgroundTransparency = 1\n\t\tglow.Image = "rbxassetid://6014261993"\n\t\tglow.ImageColor3 = Color3.fromRGB(255, 255, 255)\n\t\tglow.ImageTransparency = 0.55\n\t\tglow.ScaleType = Enum.ScaleType.Slice\n\t\tglow.SliceCenter = Rect.new(49, 49, 450, 450)\n\t\tglow.ZIndex = 4\n\t\tglow.Parent = revSliderHandle\n\tend)\n\n\trevSliderValLabel = new("TextLabel", {\n\t\tAnchorPoint = Vector2.new(1, 0),\n\t\tPosition = UDim2.new(1, 0, 0, 32),\n\t\tSize = UDim2.fromOffset(40, 20),\n\t\tBackgroundTransparency = 1,\n\t\tText = "1.0x",\n\t\tTextColor3 = T.danger,\n\t\tTextSize = 10.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Right,\n\t\tParent = reverseCard,\n\t})\n\n\tnew("TextLabel", {\n\t\tSize = UDim2.fromOffset(110, 16),\n\t\tPosition = UDim2.fromOffset(0, 56),\n\t\tBackgroundTransparency = 1,\n\t\tText = "Rev Speed Slots:",\n\t\tTextColor3 = T.text3,\n\t\tTextSize = 8.5,\n\t\tFont = Enum.Font.BuilderSansBold,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tParent = reverseCard,\n\t})\n\treverseContentContainer = new("Frame", {\n\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\tPosition = UDim2.fromOffset(0, 72),\n\t\tBackgroundTransparency = 1,\n\t\tParent = reverseCard,\n\t})\n\tend\nlocal function importFromLumen(manualTrigger)\n\t\tlocal importedAnimsCount = 0\n\t\tlocal importedBindsCount = 0\n\n\t\t-- Ensure customs folder exists\n\t\tif not isfolder(customsFolderPath) then\n\t\t\tmakefolder(customsFolderPath)\n\t\tend\n\n\t\t-- Pre-resolve the Lumen folder to prevent redundant file checks\n\t\tlocal resolvedFolder = nil\n\t\tlocal foldersToCheck = {"ReanimData", "Lumen/reanim/customs", "Lumen/reanim/customs", "Lumen/reanim", "Lumen"}\n\t\tfor _, f in ipairs(foldersToCheck) do\n\t\t\tif isfolder and isfolder(f) then\n\t\t\t\tresolvedFolder = f\n\t\t\t\tbreak\n\t\t\tend\n\t\tend\n\n\t\t-- Helper function: read a file from ReanimData/ folder or relative path\n\t\tlocal function readLumenFile(fname)\n\t\t\tif resolvedFolder then\n\t\t\t\tlocal path = resolvedFolder .. "/" .. fname\n\t\t\t\tlocal ok, res = pcall(readfile, path)\n\t\t\t\tif ok and type(res) == "string" and res ~= "" then\n\t\t\t\t\treturn res\n\t\t\t\tend\n\t\t\tend\n\t\t\tlocal paths = {\n\t\t\t\t"ReanimData/" .. fname,\n\t\t\t\tfname,\n\t\t\t\t"Lumen/reanim/" .. fname,\n\t\t\t\t"Lumen/" .. fname\n\t\t\t}\n\t\t\tfor _, p in ipairs(paths) do\n\t\t\t\tlocal ok, res = pcall(readfile, p)\n\t\t\t\tif ok and type(res) == "string" and res ~= "" then\n\t\t\t\t\treturn res\n\t\t\t\tend\n\t\t\tend\n\t\t\treturn nil\n\t\tend\n\n\t\t-- Helper function: decode JSON safely\n\t\tlocal function decodeJSON(str)\n\t\t\tif not str or str == "" then return nil end\n\t\t\tlocal cleaned = str:gsub("^" .. string.char(239, 187, 191), ""):gsub("\\r\\n", "\\n"):gsub("\\r", "\\n")\n\t\t\tlocal ok, res = pcall(function() return httpService:JSONDecode(cleaned) end)\n\t\t\treturn ok and type(res) == "table" and res or nil\n\t\tend\n\n\t\t-- Batch file saving queue\n\t\tlocal filesToSave = {}\n\n\t\t-- Helper function: queue animation for saving (don\'t save immediately)\n\t\tlocal function queueAnimForSaving(name, content)\n\t\t\tif not name or not content or name == "" or content == "" then return false end\n\t\t\tlocal safeName = name:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")\n\t\t\tif safeName == "" then return false end\n\n\t\t\tfilesToSave[safeName] = content\n\t\t\treturn true\n\t\tend\n\n\t\t-- Helper function: save all queued files in batches\n\t\tlocal function saveQueuedFiles()\n\t\t\tlocal count = 0\n\t\t\tfor name, content in pairs(filesToSave) do\n\t\t\t\tcount = count + 1\n\t\t\t\tif count % 2 == 0 then\n\t\t\t\t\ttask.wait(0.05) -- Yield every 2 file writes with shorter wait\n\t\t\t\tend\n\t\t\t\tlocal filePath = customsFolderPath .. "/" .. name .. ".lua"\n\t\t\t\tpcall(writefile, filePath, content)\n\t\t\tend\n\t\tend\n\n\t\t-- 1. Import Custom Animations from Lumen index / catalog files\n\t\tlocal customCatalogNames = {\n\t\t\t"lumen_custom_anims.json",\n\t\t\t"ReanimCustomAnims.json",\n\t\t\t"index.json",\n\t\t\t"LumenAnimations.json",\n\t\t\t"CustomAnims.json",\n\t\t\t"custom_animations.json",\n\t\t\t"LumenCustomAnims.json"\n\t\t}\n\n\t\tlocal batchCounter = 0\n\t\tfor _, catName in ipairs(customCatalogNames) do\n\t\t\tlocal rawJson = readLumenFile(catName)\n\t\t\tlocal data = decodeJSON(rawJson)\n\t\t\tif data then\n\t\t\t\t-- Handle Array Format\n\t\t\t\tfor _, entry in ipairs(data) do\n\t\t\t\t\tbatchCounter = batchCounter + 1\n\t\t\t\t\tif batchCounter >= 10 then\n\t\t\t\t\t\ttask.wait(0.02) -- Yield every 10 items with shorter wait\n\t\t\t\t\t\tbatchCounter = 0\n\t\t\t\t\tend\n\t\t\t\t\tif type(entry) == "table" then\n\t\t\t\t\t\tlocal animName = entry.name or entry.Name\n\t\t\t\t\t\tlocal animContent = entry.url or entry.file or entry.code or entry.script or entry.id or entry.Id or (entry.animData and httpService:JSONEncode(entry.animData))\n\n\t\t\t\t\t\tif type(animContent) == "number" or (type(animContent) == "string" and animContent:match("^%d+$")) then\n\t\t\t\t\t\t\tanimContent = "rbxassetid://" .. tostring(animContent)\n\t\t\t\t\t\telseif type(animContent) == "string" and (animContent:match("%.dat$") or animContent:match("%.lua$") or animContent:match("%.json$") or animContent:find("/")) then\n\t\t\t\t\t\t\tlocal fileData = readLumenFile(animContent) or readLumenFile((animContent:gsub("^ReanimData/", "")))\n\t\t\t\t\t\t\tif fileData then animContent = fileData end\n\t\t\t\t\t\tend\n\n\t\t\t\t\t\tif animName and animContent and animName ~= "" and type(animContent) == "string" and animContent ~= "" then\n\t\t\t\t\t\t\tlocal sanitized = animName:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")\n\t\t\t\t\t\t\tif sanitized ~= "" and not transformCache[sanitized] then\n\t\t\t\t\t\t\t\t-- Queue for saving (don\'t save yet)\n\t\t\t\t\t\t\t\tif queueAnimForSaving(sanitized, animContent) then\n\t\t\t\t\t\t\t\t\ttransformCache[sanitized] = animContent\n\t\t\t\t\t\t\t\t\timportedAnimsCount = importedAnimsCount + 1\n\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\n\t\t\t\t-- Handle Dictionary Format\n\t\t\t\tfor key, val in pairs(data) do\n\t\t\t\t\tbatchCounter = batchCounter + 1\n\t\t\t\t\tif batchCounter >= 10 then\n\t\t\t\t\t\ttask.wait(0.02) -- Yield every 10 items with shorter wait\n\t\t\t\t\t\tbatchCounter = 0\n\t\t\t\t\tend\n\t\t\t\t\tif type(key) == "string" and (type(val) == "string" or type(val) == "number" or type(val) == "table") then\n\t\t\t\t\t\tlocal animScript = type(val) == "string" and val or (type(val) == "number" and "rbxassetid://" .. tostring(val)) or (val.code or val.script or val.url or val.id or (val.animData and httpService:JSONEncode(val.animData)))\n\t\t\t\t\t\tif type(animScript) == "string" then\n\t\t\t\t\t\t\tif animScript:match("^%d+$") then\n\t\t\t\t\t\t\t\tanimScript = "rbxassetid://" .. animScript\n\t\t\t\t\t\t\telseif animScript:match("%.dat$") or animScript:match("%.lua$") or animScript:find("/") then\n\t\t\t\t\t\t\t\tlocal fileData = readLumenFile(animScript) or readLumenFile((animScript:gsub("^ReanimData/", "")))\n\t\t\t\t\t\t\t\tif fileData then animScript = fileData end\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tlocal sanitized = key:gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")\n\t\t\t\t\t\t\tif sanitized ~= "" and not transformCache[sanitized] then\n\t\t\t\t\t\t\t\t-- Queue for saving (don\'t save yet)\n\t\t\t\t\t\t\t\tif queueAnimForSaving(sanitized, animScript) then\n\t\t\t\t\t\t\t\t\ttransformCache[sanitized] = animScript\n\t\t\t\t\t\t\t\t\timportedAnimsCount = importedAnimsCount + 1\n\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\t-- 2. Scan ReanimData/ folder for raw custom animation files\n\t\tlocal lumenFolders = {"Lumen/reanim/customs", "Lumen/reanim", "Lumen/reanim/customs", "customs", "ReanimData", "Lumen/reanim/customs", "Lumen/reanim/customs"}\n\t\tlocal lumenIgnoredFiles = {\n\t\t\treanimfavorites = true,\n\t\t\treanimkeybinds = true,\n\t\t\treanimspeedkeys = true,\n\t\t\treanimstates = true,\n\t\t\tonlineanimationscache = true,\n\t\t\tindex = true,\n\t\t\treanimcustomanims = true,\n\t\t\treanimautoimportdone = true,\n\t\t\teditorpreview = true,\n\t\t\treanimreversekey = true,\n\t\t\treanimreversespeed = true,\n\t\t\treanimrevspeedkeys = true,\n\t\t\treanimfortnitewheelkey = true,\n\t\t\treanimmobilewheelbtn = true\n\t\t}\n\n\t\tbatchCounter = 0\n\t\tfor _, folder in ipairs(lumenFolders) do\n\t\t\tif isfolder and isfolder(folder) then\n\t\t\t\tlocal ok, files = pcall(listfiles, folder)\n\t\t\t\tif ok and type(files) == "table" then\n\t\t\t\t\tfor _, f in ipairs(files) do\n\t\t\t\t\t\tbatchCounter = batchCounter + 1\n\t\t\t\t\t\tif batchCounter >= 10 then\n\t\t\t\t\t\t\ttask.wait(0.02) -- Yield every 10 files with shorter wait\n\t\t\t\t\t\t\tbatchCounter = 0\n\t\t\t\t\t\tend\n\n\t\t\t\t\t\tlocal cleanF = f:gsub("\\\\\\\\", "/"):gsub("\\\\", "/")\n\t\t\t\t\t\tlocal fileBase = cleanF:match("([^/]+)$")\n\t\t\t\t\t\tif fileBase then\n\t\t\t\t\t\t\tlocal extStart = fileBase:find("%.[^%.]+$")\n\t\t\t\t\t\t\tlocal ext = extStart and fileBase:sub(extStart):lower() or ""\n\t\t\t\t\t\t\tlocal rawName = extStart and fileBase:sub(1, extStart - 1) or fileBase\n\n\t\t\t\t\t\t\tlocal lowerName = rawName:lower()\n\t\t\t\t\t\t\tif ext == ".lua" or ext == ".json" or ext == ".txt" or ext == ".dat" or ext == "" then\n\t\t\t\t\t\t\t\tif not lowerName:match("^anim_%d+$") and not lumenIgnoredFiles[lowerName] and not lowerName:match("[Ss]ettings") and not lowerName:match("[Cc]onfig") then\n\t\t\t\t\t\t\t\t\tlocal cleanName = rawName:gsub("^custom_", ""):gsub("[^%w%s%-_%$%#%@%!]", ""):match("^%s*(.-)%s*$")\n\t\t\t\t\t\t\t\t\tif cleanName ~= "" and not transformCache[cleanName] then\n\t\t\t\t\t\t\t\t\t\tlocal okRead, code = pcall(readfile, folder .. "/" .. fileBase)\n\t\t\t\t\t\t\t\t\t\tif okRead and type(code) == "string" and code ~= "" then\n\t\t\t\t\t\t\t\t\t\t\t-- Queue for saving (don\'t save yet)\n\t\t\t\t\t\t\t\t\t\t\tif queueAnimForSaving(cleanName, code) then\n\t\t\t\t\t\t\t\t\t\t\t\ttransformCache[cleanName] = code\n\t\t\t\t\t\t\t\t\t\t\t\timportedAnimsCount = importedAnimsCount + 1\n\t\t\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\t-- 3. Import Favorites\n\t\tlocal rawFavs = decodeJSON(readLumenFile("ReanimFavorites.json")) or decodeJSON(readLumenFile("LumenFavorites.json"))\n\t\tif rawFavs then\n\t\t\tfor name, isFav in pairs(rawFavs) do\n\t\t\t\tif isFav == true then\n\t\t\t\t\tlocal sanitized = tostring(name):gsub("^%[Custom%]%s*", ""):gsub("[^%w%s%-_$]", ""):match("^%s*(.-)%s*$")\n\t\t\t\t\tif sanitized ~= "" then\n\t\t\t\t\t\tcharacterAttachments[sanitized] = true\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\t-- 4. Import States\n\t\tlocal rawStates = decodeJSON(readLumenFile("ReanimStates.json")) or decodeJSON(readLumenFile("LumenStates.json"))\n\t\tif rawStates then\n\t\t\tfor stateKey, stateVal in pairs(rawStates) do\n\t\t\t\tlocal animCodeOrPath = type(stateVal) == "string" and stateVal or (type(stateVal) == "table" and (stateVal.url or stateVal.file or stateVal.code) or nil)\n\t\t\t\tif animCodeOrPath then\n\t\t\t\t\tif type(animCodeOrPath) == "string" and (animCodeOrPath:match("%.dat$") or animCodeOrPath:match("%.lua$") or animCodeOrPath:match("%.txt$") or animCodeOrPath:find("/")) then\n\t\t\t\t\t\tlocal fileData = readLumenFile(animCodeOrPath) or readLumenFile((animCodeOrPath:gsub("^ReanimData/", "")))\n\t\t\t\t\t\tif fileData then animCodeOrPath = fileData end\n\t\t\t\t\tend\n\t\t\t\t\tlocal sKey = tostring(stateKey):lower()\n\t\t\t\t\tstateAnimations[sKey] = animCodeOrPath\n\t\t\t\t\tif sKey == "idle" or sKey == "walking" or sKey == "jumping" or sKey == "running" or sKey == "falling" or sKey == "climbing" then\n\t\t\t\t\t\tstateAnimations[sKey] = animCodeOrPath\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\tif writefile and isfolder and isfolder("Lumen/reanim") then\n\t\t\t\tpcall(writefile, stateAnimationsPath, httpService:JSONEncode(stateAnimations))\n\t\t\tend\n\t\tend\n\n\t\t-- Save favorites and keybinds\n\t\tsaveFavoriteAnimations()\n\t\tapplyAnimationKeybinds()\n\n\t\t-- Now save all queued animation files in batches (this is the slow part)\n\t\ttask.wait(0.1)\n\t\tsaveQueuedFiles()\n\n\t\t-- Refresh UI\n\t\ttask.wait(0.1)\n\t\tpcall(initializeGui)\n\t\ttask.wait(0.1)\n\t\tif loadGUI then pcall(loadGUI) end\n\t\treturn true, importedAnimsCount, importedBindsCount\n\tend\n\n\t-- Auto-import disabled - use the Import button in settings instead\nlocal function importFromAK()\n\t\tlocal pathsToCheck = {\n\t\t\t"custom_animations.json",\n\t\t\t"workspace/custom_animations.json",\n\t\t\t"ak/custom_animations.json",\n\t\t\t"../workspace/custom_animations.json"\n\t\t}\n\t\tlocal raw = nil\n\t\tfor _, path in ipairs(pathsToCheck) do\n\t\t\tlocal ok, content = pcall(readfile, path)\n\t\t\tif ok and content and content ~= "" then\n\t\t\t\traw = content\n\t\t\t\tbreak\n\t\t\tend\n\t\tend\n\n\t\tif raw then\n\t\t\tlocal cleaned = raw:gsub("^" .. string.char(239, 187, 191), ""):gsub("\\r\\n", "\\n"):gsub("\\r", "\\n")\n\t\t\tlocal ok2, data = pcall(function() return httpService:JSONDecode(cleaned) end)\n\t\t\tif ok2 and type(data) == "table" then\n\t\t\t\tlocal count = 0\n\t\t\t\tfor key, val in pairs(data) do\n\t\t\t\t\tlocal animName, animScript\n\t\t\t\t\tif type(key) == "string" and type(val) == "string" then\n\t\t\t\t\t\tanimName, animScript = key, val\n\t\t\t\t\tend\n\n\t\t\t\t\tif animName and animScript and animName ~= "" and animScript ~= "" then\n\t\t\t\t\t\tlocal sanitizedName = animName:gsub("[^%w%s%-_]",""):match("^%s*(.-)%s*$")\n\t\t\t\t\t\tif sanitizedName ~= "" and not transformCache[sanitizedName] then\n\t\t\t\t\t\t\ttransformCache[sanitizedName] = animScript\n\t\t\t\t\t\t\tcount = count + 1\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\n\t\t\t\tlocal kbData = {}\n\t\t\t\tlocal kbPaths = {\n\t\t\t\t\t"animation_keybinds.json",\n\t\t\t\t\t"workspace/animation_keybinds.json",\n\t\t\t\t\t"ak/animation_keybinds.json",\n\t\t\t\t\t"../workspace/animation_keybinds.json"\n\t\t\t\t}\n\t\t\t\tfor _, path in ipairs(kbPaths) do\n\t\t\t\t\tlocal ok, content = pcall(readfile, path)\n\t\t\t\t\tif ok and content and content ~= "" then\n\t\t\t\t\t\tlocal kbCleaned = content:gsub("^" .. string.char(239, 187, 191), ""):gsub("\\r\\n", "\\n"):gsub("\\r", "\\n")\n\t\t\t\t\t\tlocal ok3, parsedKb = pcall(function() return httpService:JSONDecode(kbCleaned) end)\n\t\t\t\t\t\tif ok3 and type(parsedKb) == "table" then\n\t\t\t\t\t\t\tkbData = parsedKb\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\n\t\t\t\tlocal boundCount = 0\n\t\t\t\tfor name, keyName in pairs(kbData) do\n\t\t\t\t\tlocal sanitizedName = name:gsub("[^%w%s%-_]",""):match("^%s*(.-)%s*$")\n\t\t\t\t\tif type(keyName) == "string" then\n\t\t\t\t\t\tlocal kc = Enum.KeyCode[keyName]\n\t\t\t\t\t\tif kc and (transformCache[sanitizedName] or animationQueue[sanitizedName]) then\n\t\t\t\t\t\t\tanimationBindings[sanitizedName] = kc\n\t\t\t\t\t\t\tboundCount = boundCount + 1\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\n\t\t\t\tsaveFavoriteAnimations()\n\t\t\t\tapplyAnimationKeybinds()\n\t\t\t\treturn true, count, boundCount\n\t\t\tend\n\t\tend\n\n\t\treturn false, 0, 0\n\tend\n\n\tlocal currentNamesList = {}\n\tlocal currentListToUse = {}\n\tlocal currentRenderedCount = 0\n\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- ROW RENDERING (Matching Lumen V2 List Items)\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\t-- ROW RENDERING (Matching Lumen V2 List Cards)\n\t-- \u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\u{2550}\n\tlocal function renderRow(name, id)\n\t\tlocal item = new("Frame", {\n\t\t\tSize = UDim2.new(1, 0, 0, 36),\n\t\t\tBackgroundColor3 = T.surface2,\n\t\t\tBackgroundTransparency = 0.35,\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = scrollContainer,\n\t\t}, { corner(8), pad(0, 10, 0, 12) })\n\t\tstroke(T.line, 1, 0.45).Parent = item\n\n\t\tlocal playBtn = new("TextButton", {\n\t\t\tBackgroundTransparency = 1,\n\t\t\tText = (name:sub(-4):lower() == ".lua") and name:sub(1, -5) or name,\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 11,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tFont = Enum.Font.BuilderSansMedium,\n\t\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\t\tClipsDescendants = true,\n\t\t\tParent = item,\n\t\t})\n\n\t\tlocal isFav = characterAttachments[name] ~= nil\n\t\tlocal favBtn = new("ImageButton", {\n\t\t\tSize = UDim2.fromOffset(28, 22),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tScaleType = Enum.ScaleType.Fit,\n\t\t\tImageColor3 = Color3.fromRGB(255, 255, 255),\n\t\t\tParent = item,\n\t\t}, { corner(5), pad(3, 6, 3, 6) })\n\t\tsetIconId(favBtn, isFav and unfavIconId or favIconId)\n\t\tstroke(T.line, 1, 0.5).Parent = favBtn\n\n\t\tlocal actionBtn = new("ImageButton", {\n\t\t\tSize = UDim2.fromOffset(36, 22),\n\t\t\tBackgroundColor3 = T.surface3,\n\t\t\tScaleType = Enum.ScaleType.Fit,\n\t\t\tBorderSizePixel = 0,\n\t\t\tAutoButtonColor = false,\n\t\t\tParent = item,\n\t\t}, { corner(5) })\n\t\tstroke(T.line, 1, 0.5).Parent = actionBtn\n\n\t\tlocal actionText = new("TextLabel", {\n\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tTextColor3 = T.text1,\n\t\t\tTextSize = 8.5,\n\t\t\tFont = Enum.Font.BuilderSansBold,\n\t\t\tVisible = false,\n\t\t\tParent = actionBtn,\n\t\t})\n\n\t\tlocal function updateActionBtnDisplay()\n\t\t\tif animationBindings[name] then\n\t\t\t\tactionBtn.Image = ""\n\t\t\t\tactionText.Text = animationBindings[name].Name:sub(1,3)\n\t\t\t\tactionText.Visible = true\n\t\t\telse\n\t\t\t\tsetIconId(actionBtn, keybindIconId)\n\t\t\t\tactionText.Visible = false\n\t\t\tend\n\t\tend\n\t\tupdateActionBtnDisplay()\n\t\tlocal delBtn = nil\n\t\tif characterModel4 == "custom" then\n\t\t\tplayBtn.Position = UDim2.new(0, 0, 0, 0)\n\t\t\tplayBtn.Size = UDim2.new(1, -140, 1, 0)\n\t\t\tfavBtn.AnchorPoint = Vector2.new(1, 0.5)\n\t\t\tfavBtn.Position = UDim2.new(1, -74, 0.5, 0)\n\t\t\tactionBtn.AnchorPoint = Vector2.new(1, 0.5)\n\t\t\tactionBtn.Position = UDim2.new(1, -30, 0.5, 0)\n\t\t\tdelBtn = new("ImageButton", {\n\t\t\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\t\t\tPosition = UDim2.new(1, 0, 0.5, 0),\n\t\t\t\tSize = UDim2.fromOffset(18, 18),\n\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\tScaleType = Enum.ScaleType.Fit,\n\t\t\t\tImage = delIconId,\n\t\t\t\tParent = item,\n\t\t\t})\n\t\telse\n\t\t\tplayBtn.Position = UDim2.new(0, 0, 0, 0)\n\t\t\tplayBtn.Size = UDim2.new(1, -110, 1, 0)\n\t\t\tfavBtn.AnchorPoint = Vector2.new(1, 0.5)\n\t\t\tfavBtn.Position = UDim2.new(1, -44, 0.5, 0)\n\t\t\tactionBtn.AnchorPoint = Vector2.new(1, 0.5)\n\t\t\tactionBtn.Position = UDim2.new(1, 0, 0.5, 0)\n\t\tend\n\t\tplayBtn.MouseButton1Click:Connect(function()\n\t\t\tdecodedResponse(tostring(id), name)\n\t\tend)\n\t\tfavBtn.MouseButton1Click:Connect(function()\n\t\t\tif characterAttachments[name] then\n\t\t\t\tcharacterAttachments[name] = nil\n\t\t\t\tsetIconId(favBtn, favIconId)\n\t\t\telse\n\t\t\t\tcharacterAttachments[name] = tostring(id)\n\t\t\t\tsetIconId(favBtn, unfavIconId)\n\t\t\tend\n\t\t\tsaveFavoriteAnimations()\n\t\t\tif characterModel4 == "favorites" then loadGUI() end\n\t\tend)\n\n\t\tif delBtn then\n\t\t\tdelBtn.MouseButton1Click:Connect(function()\n\t\t\t\ttransformCache[name] = nil\n\t\t\t\tanimationQueue[name] = nil\n\t\t\t\tpcall(function()\n\t\t\t\t\tlocal sanitized = name:gsub("[^%w%s%-_]",""):match("^%s*(.-)%s*$")\n\t\t\t\t\tif delfile then\n\t\t\t\t\t\tdelfile(customsFolderPath .. "/" .. sanitized .. ".lua")\n\t\t\t\t\t\tdelfile(customsFolderPath .. "/" .. sanitized .. ".json")\n\t\t\t\t\tend\n\t\t\t\tend)\n\t\t\t\tinitializeGui()\n\t\t\t\tloadGUI()\n\t\t\tend)\n\t\tend\n\n\t\tactionBtn.MouseButton1Click:Connect(function()\n\t\t\tif animationBindings[name] then\n\t\t\t\tanimationBindings[name] = nil\n\t\t\t\tapplyAnimationKeybinds()\n\t\t\t\tupdateActionBtnDisplay()\n\t\t\telse\n\t\t\t\tactionBtn.Image = ""\n\t\t\t\tactionText.Text = "..."\n\t\t\t\tactionText.Visible = true\n\t\t\t\tisSettingBind = true\n\t\t\t\tlocal connection\n\t\t\t\tconnection = userInputService.InputBegan:Connect(function(input)\n\t\t\t\t\tif input.UserInputType == Enum.UserInputType.Keyboard then\n\t\t\t\t\t\tif input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then\n\t\t\t\t\t\t\tconnection:Disconnect()\n\t\t\t\t\t\t\tupdateActionBtnDisplay()\n\t\t\t\t\t\t\tisSettingBind = false\n\t\t\t\t\t\telseif input.KeyCode ~= Enum.KeyCode.Unknown then\n\t\t\t\t\t\t\tanimationBindings[name] = input.KeyCode\n\t\t\t\t\t\t\tapplyAnimationKeybinds()\n\t\t\t\t\t\t\tupdateActionBtnDisplay()\n\t\t\t\t\t\t\tconnection:Disconnect()\n\t\t\t\t\t\t\ttask.defer(function() isSettingBind = false end)\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend)\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal function loadMoreItems()\n\t\tif currentRenderedCount >= #currentNamesList then return end\n\t\tlocal batchSize = 35\n\t\tlocal myGen = currentActiveGen\n\t\tlocal startIdx = currentRenderedCount + 1\n\t\tlocal endIdx = math.min(startIdx + batchSize - 1, #currentNamesList)\n\t\tcurrentRenderedCount = endIdx\n\t\ttask.spawn(function()\n\t\t\tfor i = startIdx, endIdx do\n\t\t\t\tif myGen ~= currentActiveGen then return end\n\t\t\t\tlocal name = currentNamesList[i]\n\t\t\t\tlocal id = currentListToUse[name]\n\t\t\t\trenderRow(name, id)\n\t\t\t\tif i % 6 == 0 then task.wait() end\n\t\t\tend\n\t\tend)\n\tend\n\n\tfunction loadGUI()\n\t\tcurrentActiveGen = currentActiveGen + 1\n\t\tfor _, child in ipairs(scrollContainer:GetChildren()) do\n\t\t\tif child:IsA("Frame") then child:Destroy() end\n\t\tend\n\t\tlocal query = searchBox.Text:lower()\n\t\tlocal listToUse = {}\n\t\tif characterModel4 == "all" then\n\t\t\tfor name, id in pairs(animationQueue) do\n\t\t\t\tif not transformCache[name] then listToUse[name] = id end\n\t\t\tend\n\t\telseif characterModel4 == "favorites" then\n\t\t\tfor name, id in pairs(characterAttachments) do listToUse[name] = id end\n\t\telseif characterModel4 == "custom" then\n\t\t\tfor name, id in pairs(transformCache) do listToUse[name] = id end\n\t\telseif characterModel4 == "binds" then\n\t\t\tfor name, key in pairs(animationBindings) do\n\t\t\t\tlocal id = animationQueue[name] or transformCache[name] or characterAttachments[name] or "0"\n\t\t\t\tlistToUse[name] = id\n\t\t\tend\n\t\tend\n\t\tlocal sortedNames = {}\n\t\tfor name in pairs(listToUse) do\n\t\t\tif query == "" or name:lower():find(query, 1, true) ~= nil then\n\t\t\t\ttable.insert(sortedNames, name)\n\t\t\tend\n\t\tend\n\t\ttable.sort(sortedNames)\n\t\tcurrentNamesList = sortedNames\n\t\tcurrentListToUse = listToUse\n\t\tcurrentRenderedCount = 0\n\t\tloadMoreItems()\n\tend\n\n\tlocal tabSearch = {}\n\tfunction selectCategory(catName)\n\t\t-- every list tab keeps its own search text\n\t\ttabSearch[characterModel4] = searchBox.Text\n\t\tcharacterModel4 = catName\n\t\tsearchBox.Text = tabSearch[catName] or ""\n\t\tfor id, bData in pairs(tabButtons) do\n\t\t\tlocal isActive = (id == catName)\n\t\t\ttween(bData.btn, SPRING_FAST, {\n\t\t\t\tTextColor3 = isActive and T.text1 or T.text3,\n\t\t\t\tBackgroundColor3 = isActive and T.surface3 or T.surface,\n\t\t\t\tBackgroundTransparency = isActive and 0 or 0.45,\n\t\t\t})\n\t\t\tif bData.stroke then\n\t\t\t\ttween(bData.stroke, SPRING_FAST, {\n\t\t\t\t\tColor = isActive and Color3.fromRGB(255, 255, 255) or T.line,\n\t\t\t\t\tTransparency = isActive and 0.75 or 0.45,\n\t\t\t\t})\n\t\t\tend\n\t\tend\n\t\tonSubmitInput()\n\t\tif selectModal then selectModal.Visible = false end\n\t\tif catName == "all" or catName == "favorites" or catName == "custom" or catName == "binds" then\n\t\t\tloadGUI()\n\t\tend\n\tend\n\n\taddSubmitBtn.MouseButton1Click:Connect(function()\n\t\tlocal name = inputBox.Text\n\t\tlocal code = fullCode ~= "" and fullCode or sliderInput.Text\n\t\tif name == "" or code == "" then\n\t\t\tcurrentlyPlayingLabel.Text = "Name and code required!"\n\t\t\ttask.spawn(function()\n\t\t\t\ttask.wait(2)\n\t\t\t\tif currentlyPlayingLabel then currentlyPlayingLabel.Text = "Playing: None" end\n\t\t\tend)\n\t\t\treturn\n\t\tend\n\t\tlocal sanitizedName = name:gsub("[^%w%s%-_]",""):match("^%s*(.-)%s*$")\n\t\tif sanitizedName ~= "" then\n\t\t\tpcall(function()\n\t\t\t\tif writefile then\n\t\t\t\t\tif not isfolder(customsFolderPath) then makefolder(customsFolderPath) end\n\t\t\t\t\twritefile(customsFolderPath .. "/" .. sanitizedName .. ".lua", code)\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\t\ttransformCache[name] = code\n\t\tanimationQueue[name] = code\n\t\tinitializeGui()\n\t\tinputBox.Text = ""\n\t\tfullCode, codePreview = "", nil\n\t\tsliderInput.Text = ""\n\t\tcurrentlyPlayingLabel.Text = "Saved: " .. name\n\t\ttask.spawn(function()\n\t\t\ttask.wait(2)\n\t\t\tif currentlyPlayingLabel then currentlyPlayingLabel.Text = "Playing: None" end\n\t\tend)\n\t\tif characterModel4 == "custom" then loadGUI() end\n\tend)\n\n\tlocal function updateSpeedSlider(speed)\n\t\tspeed = math.clamp(speed, 0.1, 10.0)\n\t\tanimationContext.speed = speed\n\t\tlocal fraction = math.clamp((speed - 0.1) / 3.9, 0, 1)\n\t\tglide(sliderFill, { Size = UDim2.new(fraction, 0, 1, 0) })\n\t\tlocal handleOffset = (1 - 2 * fraction) * (35 / 2 - 2)\n\t\tglide(sliderHandle, { Position = UDim2.new(fraction, handleOffset, 0.5, 0) })\n\t\tsliderValueLabel.Text = string.format("%.1fx", speed)\n\t\tpcall(lumenAPI.set_animation_speed, speed)\n\tend\n\n\tlocal sliderDragging = false\n\tsliderHandle.InputBegan:Connect(function(input)\n\t\tif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then\n\t\t\tsliderDragging = true\n\t\t\tinput.Changed:Connect(function()\n\t\t\t\tif input.UserInputState == Enum.UserInputState.End then sliderDragging = false end\n\t\t\tend)\n\t\tend\n\tend)\n\tuserInputService.InputChanged:Connect(function(input)\n\t\tif sliderDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then\n\t\t\tlocal scale = math.clamp((input.Position.X - sliderBackground.AbsolutePosition.X) / sliderBackground.AbsoluteSize.X, 0, 1)\n\t\t\tupdateSpeedSlider(0.1 + scale * 3.9)\n\t\tend\n\tend)\n\tresetButton3.MouseButton1Click:Connect(function() updateSpeedSlider(1.0) end)\n\n\tlocal function updateRevSpeedSlider(speed)\n\t\tspeed = math.clamp(speed, 0.1, 10.0)\n\t\tGlobalReverseSpeed = speed\n\t