nction sync()\n\t\t\t\tlocal p, sz = frame.Position, frame.Size\n\t\t\t\tfB.Visible = frame.Visible\n\t\t\t\tfB.Position = UDim2.new(p.X.Scale, p.X.Offset, p.Y.Scale + sz.Y.Scale, p.Y.Offset + sz.Y.Offset)\n\t\t\t\tfB.Size = UDim2.new(sz.X.Scale, sz.X.Offset, 0, 22)\n\t\t\tend\n\t\t\tsync()\n\t\t\tframe:GetPropertyChangedSignal("Visible"):Connect(sync)\n\t\t\tframe:GetPropertyChangedSignal("Position"):Connect(sync)\n\t\t\tframe:GetPropertyChangedSignal("Size"):Connect(sync)\n\t\tend\n\t\tif false then\n\t\t\tfor _, f in ipairs({ scrollContainer, speedsPanelFrame, statesPanelFrame, trackersPanelFrame, combinePanelFrame, recordPanelFrame, settingsPanelFrame }) do\n\t\t\t\tpcall(addFades, f)\n\t\t\tend\n\t\tend\n\tend\n\n\tfunction onSubmitInput()\n\t\toptionFrame.Visible = false\n\t\tsettingsPanelFrame.Visible = false\n\t\tscrollContainer.Visible = false\n\t\tsearchBox.Visible = false\n\t\tspeedsPanelFrame.Visible = false\n\t\tstatesPanelFrame.Visible = false\n\t\ttrackersPanelFrame.Visible = false\n\t\tcombinePanelFrame.Visible = false\n\t\trecordPanelFrame.Visible = false\n\n\t\tif characterModel4 == "custom" then\n\t\t\toptionFrame.Visible = true\n\t\t\tsearchBox.Position = UDim2.fromOffset(0, 156)\n\t\t\tsearchBox.Visible = true\n\t\t\tscrollContainer.Position = UDim2.fromOffset(0, 194)\n\t\t\tscrollContainer.Size = UDim2.new(1, 0, 1, -200)\n\t\t\tscrollContainer.Visible = true\n\t\telseif characterModel4 == "settings" then\n\t\t\tsettingsPanelFrame.Visible = true\n\t\telseif characterModel4 == "speed" then\n\t\t\tspeedsPanelFrame.Visible = true\n\t\telseif characterModel4 == "states" then\n\t\t\tstatesPanelFrame.Visible = true\n\t\t\tselectModal.Visible = false\n\t\telseif characterModel4 == "tracker" then\n\t\t\ttrackersPanelFrame.Visible = true\n\t\telseif characterModel4 == "combine" then\n\t\t\tcombinePanelFrame.Visible = true\n\t\t\tpcall(refreshCombinePanel)\n\t\telseif characterModel4 == "record" then\n\t\t\trecordPanelFrame.Visible = true\n\t\telse\n\t\t\